begin;
create table if not exists public.scene_map_catalog (
  catalog_id text primary key check (catalog_id = 'bank-main'),
  schema_version integer not null check (schema_version in (1,2,3)),
  release_id text not null,
  content_sha256 text not null check (content_sha256 ~ '^[a-f0-9]{64}$'),
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  updated_at timestamptz not null default now()
);
alter table public.scene_map_catalog drop constraint if exists scene_map_catalog_schema_version_check;
alter table public.scene_map_catalog add constraint scene_map_catalog_schema_version_check check (schema_version in (1,2,3));
-- Serialize releases and refuse a stale SQL file overwriting a newer catalog.
lock table public.scene_map_catalog in exclusive mode;
do $release_guard$
declare current_release text;
begin
  select release_id into current_release from public.scene_map_catalog where catalog_id='bank-main';
  if current_release is not null and current_release <> '2026-10-22-v0.8.0' then
    if current_release !~ '^\d{4}-\d{2}-\d{2}-v\d+\.\d+\.\d+$' then
      raise exception 'Unrecognized current release; review before replacing';
    end if;
    if (left(current_release,10),string_to_array(split_part(current_release,'-v',2),'.')::int[]) >
       (left('2026-10-22-v0.8.0',10),string_to_array(split_part('2026-10-22-v0.8.0','-v',2),'.')::int[]) then
      raise exception 'Refusing to replace a newer catalog';
    end if;
  end if;
  if exists(select 1 from public.scene_map_catalog where catalog_id='bank-main' and release_id='2026-10-22-v0.8.0' and content_sha256 <> '5ebbf45d3f317e561c2113b41e2e8e770fa046f62b460bd8398798f2bedbba6f') then
    raise exception 'Release identity already used with another fingerprint';
  end if;
end $release_guard$;
alter table public.scene_map_catalog enable row level security;
revoke all on public.scene_map_catalog from public, anon, authenticated;
grant select on public.scene_map_catalog to anon, authenticated;
drop policy if exists scene_map_catalog_public_read on public.scene_map_catalog;
create policy scene_map_catalog_public_read on public.scene_map_catalog for select to anon, authenticated using (true);
create schema if not exists scene_map_private;
create table if not exists scene_map_private.catalog_history (
  content_sha256 text primary key, release_id text not null, payload jsonb not null,
  saved_at timestamptz not null, replaced_at timestamptz not null default now()
);
alter table scene_map_private.catalog_history enable row level security;
revoke all on scene_map_private.catalog_history from public, anon, authenticated;
insert into scene_map_private.catalog_history(content_sha256,release_id,payload,saved_at)
select content_sha256,release_id,payload,updated_at from public.scene_map_catalog
where catalog_id='bank-main' and content_sha256 <> '5ebbf45d3f317e561c2113b41e2e8e770fa046f62b460bd8398798f2bedbba6f' on conflict do nothing;

-- The whole catalog and pipeline switch together, in one transaction.
insert into public.scene_map_catalog(catalog_id,schema_version,release_id,content_sha256,payload)
values('bank-main',3,'2026-10-22-v0.8.0','5ebbf45d3f317e561c2113b41e2e8e770fa046f62b460bd8398798f2bedbba6f',$scene_catalog${"schemaVersion":3,"releaseId":"2026-10-22-v0.8.0","pipeline":{"version":"v1.3","updatedAt":"2026-10-22","summary":"从客户业务课题、数据人才作品、经营管理方案与准标杆项目中提取岗位任务，跨客户去重，经用户审核后形成场景卡片和业务地图。本轮无新增物料或场景；组织视角分列行级使用对象与落实部门，按逐卡关系派生可展开的L2导航。","method":"限定材料与证据 → 还原角色/需求/动作 → L4原子场景 → L2/L1归类（L3可选）→ 跨案例去重 → 分析使用对象与落实部门 → 用户审核 → 流水线、HTML与后台同批更新","boundary":"物料数不等于客户数或场景数；BI实践与建议AI增强分开；申报目标不等于已验证效果，预期体验不等于客户证言。原件与逐客户映射留在内部内容库。","batches":[{"id":"B01","name":"经营作战方案","projectType":"经营分析、客群作战与总支协同","materials":"1份主题分享PPT；客户名称待核实","result":"形成3个L4、1个真实L3场景群","newScenes":3},{"id":"B02","name":"数据+AI创新课题","projectType":"员工业务创新与AI应用申报","materials":"46条报名；39条有课题内容，7条信息不足","result":"拆分、归并形成34个独立场景","newScenes":34},{"id":"B03","name":"BI数据人才作品","projectType":"人才培养与业务看板竞赛","materials":"16份作品介绍及附图","result":"新增6个L4、补强8个既有L4","newScenes":6},{"id":"B04","name":"魔数工坊初赛作品","projectType":"农商行数据人才与业务分析创新","materials":"51个编号目录；50个有作品，1个仅报名表","result":"新增11个L4、补强14个既有L4","newScenes":11},{"id":"B05","name":"knowhow准标杆试点","projectType":"自助BI、经营督办、零售、绩效及数据管理","materials":"5份文档对应4个客户/机构；核读正文与1张图","result":"9个新增、7个有效补充、2个弱证据线索归档","newScenes":9},{"id":"B06","name":"企业财资服务案例提炼","projectType":"银行面向企业客户的账户资金与融资到期分析服务","materials":"同项目多载体案例及方案，按岗位需求归并；演示截图不作生产成效证据","result":"仅将本轮确认的两类企业财资任务入库，其他候选仍在审核","newScenes":2}]},"domains":[{"id":"BA01","mark":"策","name":"战略与经营管理","desc":"围绕战略规划、经营分析、绩效管理和机构督导，从看清问题走向执行反馈。","sections":[{"id":"BA01-P02","name":"经营分析与执行督导","desc":"监测经营表现，识别问题并推动研讨、督办和复盘。","scenes":[{"id":"BA01-01-01","title":"数智化经营分析会","definition":"会前汇总业绩、定位问题并形成会议材料，会后持续跟踪督办事项。","decision":"AI-L3","maturity":"实践场景 · 待核实","version":"v1.0","flagship":true,"gateway":true,"values":["管理决策","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"管理层、计财部门、业务条线、分支机构","trigger":"月度、季度或专题经营分析会准备与跟踪期间","task":"汇总目标与业绩，识别差距和根因，形成会议报告、研讨事项和督办清单。","dataScope":"经营目标、核心经营指标、机构与条线数据、历史督办事项","outputs":"经营分析报告、问题说明、研讨事项、督办清单","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：确认指标口径，选定议题，审定结论及责任人；缺数据或意见不一致时退回核查，不自动下达任务。 程序/规则：按已批准口径汇总目标和实际业绩、计算差距，生成会议数据材料；自动跟踪是案例材料方案目标，不能写已验收。 分析模型：暂不需要新增预测模型；财务分解由确定性计算承担。 大模型：建议基于已核数据生成议题和纪要草稿，不补造原因。 Agent：可建议编排取数与草稿整理；正式事项需组织者确认后进入已有任务系统，不承诺自动督办。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"经营管理人员确认指标口径、分析结论、研讨事项和正式督办任务。","before":"计财、业务条线和分支机构分别取数、核对口径并拼装材料；会后问题与任务分散跟踪。","after":"Dora 汇聚已确认指标，生成差距分析、问题说明和报告草稿，并跟踪待办变化；管理人员确认口径、结论和任务流转。","feedback":"“我能把时间从反复拼表转到问题研判，会后也能直接看到哪些事项还没有落实。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充会前材料准备人时基线、目标值和统计周期。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充指标口径一致率、异常复核率或报告差错率目标。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充督办事项按期完成率或问题闭环周期目标。"}],"quantBasis":"PPT 未提供可归属于本 L4 的可靠基线和目标值，待试点方案或项目台账补充。","scope":"已有方案、看板及 Dora 演示基础；真实客户指标范围与上线范围待项目台账核实。 本轮案例补充范围：一期财务分析材料可补强；全层级推广与督办实现待核；不据此升级整卡成熟度或AI实施状态。","boundary":"不由 AI 自动作出经营决策或直接下达正式督办任务。","assets":{"方案 PPT":"已有","看板 Demo":"已有","Dora 体验":"已有演示","短视频":"待补充"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B01","B05"]},{"id":"BA01-01-02","title":"客群经营洞察与敏捷作战","definition":"分析客群价值、经营过程和风险，形成策略研讨材料并持续跟踪目标。","decision":"AI-L2","maturity":"实践场景 · 待核实","version":"v1.0","flagship":true,"gateway":true,"values":["经营增长","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"planned","D04":"planned"},"role":"业务条线、客群经营团队","trigger":"客群规划、专项客群选择和持续经营跟踪期间","task":"分析客群价值来源、规模、经营过程和风险，支持客群选择与策略调整。","dataScope":"客群规模、财务价值、业务结构、经营过程、目标和风险指标","outputs":"客群概览、客群对比、问题定位、目标跟踪和策略研讨材料","collaboration":"当前以 Dora 和业务系统协作为主；如由外部 Agent 发起，应补充主 Agent、Dora 子任务和返回范围。","manualCheck":"业务条线确认客群口径、经营策略和执行安排。","before":"客群规模、价值、过程和风险信息分散在不同报表中，需要手工拼接后再讨论策略。","after":"Dora 按统一口径形成客群概览、对比和变化原因；业务条线确认客群定义与经营策略。","feedback":"“我能更快比较不同客群的价值和风险，把讨论重点放在该选哪类客户、怎么经营。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充客群分析材料准备时长基线和目标值。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充客群指标口径覆盖率和风险复核要求。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充重点客群策略覆盖率、跟踪频率或目标达成改善指标。"}],"quantBasis":"PPT 提供场景逻辑，但未提供可直接采用的量化目标，待业务方案确认。","scope":"客群价值与经营过程分析已有方案基础，具体指标覆盖和客户应用范围待核实。","boundary":"不把分析结果直接作为客户营销、授信或风险处置决策。","assets":{"方案 PPT":"已有","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"待补充"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B01"]},{"id":"BA01-01-03","title":"总支作战协同","definition":"定位机构差距，形成客户机会清单并跟踪客户经理的执行反馈。","decision":"AI-L3","maturity":"实践场景 · 待核实","version":"v1.1","flagship":true,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"总行管理部门、支行长、客户经理","trigger":"机构经营督导、营销专题、晨会和专项战役期间","task":"追踪机构业绩，识别营销机会，形成客户清单，分析客户经理产能并跟踪执行反馈。","dataScope":"机构目标与业绩、客户与产品机会、到期与流失信息、客户经理经营过程与产能数据","outputs":"机构诊断、营销机会清单、客户经理产能画像、专项战况和执行反馈","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：解释机构禀赋与业务约束，决定经营策略和任务安排；口径冲突回到数据责任部门核对。 程序/规则：汇总机构指标、计算增量与完成率、权限过滤和逐级钻取；并非自动生成经营因果。 分析模型：可选对标或异常检测需另外验证，不把排名当模型归因。 大模型：建议生成机构差距摘要并标注数据依据。 Agent：可建议组织跨报表材料，不自动向客户经理派任务；回录接口需另建和验证。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"支行长或业务管理人员确认机会清单、任务分配和执行要求。","before":"支行反复取数整理战况，总行要求需要人工转译到客户经理和客户清单，反馈难以连续汇总。","after":"Dora 生成机构诊断、机会清单和产能分析并汇总回执；支行长确认任务分配和执行要求。","feedback":"“我不用再花大量时间整理战况，能直接看到机会落在哪个客户经理、执行到哪一步。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充支行战况整理人时、清单生成周期和目标值。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充名单口径一致率、回录完整率和人工复核要求。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充任务触达率、按期回录率或机会转化观察指标。"}],"quantBasis":"PPT 未给出统一量化口径，待选定试点机构、任务类型和统计周期后设定。","scope":"当前以核心指标、部分归因指标及协作工具反馈为代表性实现，不代表全量指标和全流程覆盖。 本轮案例补充范围：机构指标比较、主题下钻与部分移动查询；客户机会任务、执行回执不据此验证；不据此升级整卡成熟度或AI实施状态。","boundary":"支行营销专题、到期管理、授信未用信、客户流失、产能和开门红属于本 L4 内部模块，不再增加地图层级。","assets":{"方案 PPT":"已有","看板 Demo":"已有多套材料截图","Dora 体验":"待核实","短视频":"待补充"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B01","B03","B04","B05"]}],"group":{"id":"BA01-01","title":"作战指挥中心","desc":"将经营分析、客群作战与总支协同组织为一套可持续迭代的经营管理场景群。","flagship":true,"closure":["目标承接","经营监测","问题诊断","策略研讨","任务督办","执行反馈","复盘优化"]}},{"id":"BA01-P03","name":"绩效与机构管理","desc":"跟踪机构和岗位绩效，支持资源配置与管理评价。","scenes":[{"id":"BA01-P03-S01","title":"客户经理营销绩效分析与经验复用","definition":"零售管理人员、客户经理在业绩汇总、复盘、学习环节，业绩按日自动汇总并给出个性化改进建议，优秀案例经审核后进入可检索知识库和学习任务。","decision":"AI-L2","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"零售管理人员、客户经理","trigger":"业绩汇总、复盘、学习；业务对象或触发范围：网点和个人客户经理","task":"自动清洗核心与个人上传数据→按人、日、产品汇总→绩效分析和个性化建议→经验审核入库→检索学习与复盘","dataScope":"清洗个人上传与核心数据，按人、日和产品汇总业绩并展示BI。","outputs":"编排数据处理、分析、建议推送、经验审核和学习提醒。","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：确认考核数据、解释特殊业务、决定辅导和评价；正式人事结论由有权限人员审定。 程序/规则：按规则汇总销售、计算KPI和排名，提供查看权限；正式归属和核算规则由相关场景负责。 分析模型：可选识别绩效短板，不把排名高低当因果。 大模型：建议生成辅导草稿及经授权的经验归纳，不能虚构优秀员工话术。 Agent：可建议在人工审核后组织经验入库和学习提醒，本批无实施证据。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"确认个人数据准确性，复核营销建议，审核经验和话术入库。","before":"个人业绩需人工汇总，反馈滞后，优秀员工的方法主要靠口头带教，难以规模化复用。","after":"业绩按日自动汇总并给出个性化改进建议，优秀案例经审核后进入可检索知识库和学习任务。","feedback":"“我每天都能看到自己的短板和可学案例，新人也能更快找到适合自己的提升方法。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"业绩汇总由约2小时压缩至15分钟。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"核心业绩指标一致率达到100%，经验入库人工审核率保持100%。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"营销转化率提升20%，新员工熟练度提升20%。"}],"quantBasis":"Excel“独立场景库”RW-06。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。 本轮案例补充范围：绩效查看、得分排名；知识库复用和学习闭环未证实；不据此升级整卡成熟度或AI实施状态。","boundary":"区分经营分析与正式绩效考核；个人上传数据需校验；经验入库先审核。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03","B04","B05"]},{"id":"BA01-P03-S02","title":"客户经理管户压力与风险负荷分析","definition":"管理者以多维管户压力和风险负荷识别客户经理过载与结构问题，辅助资源调配和绩效辅导。","decision":"AI-L2","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["管理决策","风险合规","客户与员工体验"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"planned"},"role":"总行管理部门、分支机构负责人、客户经理","trigger":"每日监测、任务分配、客户移交、绩效辅导和风险集中度上升时","task":"汇聚借据与客户经理数据→规则计算压力→识别过载和集中风险→形成调配建议→人工评议","dataScope":"贷款户数、用信金额、产品、担保、五级分类、逾期、投向、期限、利率和集中度。","outputs":"压力分、维度构成、风险集中点、过载预警、资源调配和辅导建议。","collaboration":"规则模型计算压力，Dora 解释构成并生成建议；人力和业务管理制度决定绩效、移交与资源安排。","manualCheck":"确认权重阈值、过载原因、客户移交、资源安排和绩效辅导。","before":"管理者只能看到客户经理“忙不忙”或结果指标，无法比较不同管户组合的复杂度和潜在风险。","after":"系统按借据每日计算17个压力维度并展示构成，识别过载与集中风险，形成可解释的调配和辅导建议。","feedback":"“我能说明压力来自哪些客户和风险结构，资源调整不再只看贷款规模或凭感觉。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"按借据粒度每日更新17个压力维度，人工评估和任务分配时长目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"识别客户、行业、担保和不良集中负荷，发现率和核查率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"服务总行、分支机构和客户经理3类角色，负荷均衡度目标待确认。"}],"scope":"已有压力指标、配置表、存储过程和BI设计；人员调配闭环与管理效果待核实。","boundary":"压力值不是心理健康评估，不得脱离岗位和组合差异直接用于绩效处罚。","assets":{"方案 PPT":"已有","看板 Demo":"材料含设计","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]},{"id":"BA01-P03-S03","title":"业绩归属与绩效核算","definition":"绩效管理人员按客户与账户的认领关系和批准规则分配业绩、计算考核结果，并处理归属差异和历史追溯。","decision":"AI-L1","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"绩效规则管理与核算人员、分支行考核负责人（岗位名称待核）","trigger":"考核周期结算、归属关系调整、规则参数变更或历史回溯","task":"在不同考核口径下确定业绩归属并生成可复核核算结果","dataScope":"客户/账户/子账户、销售人与管户关系、产品参数、考核参数与历史版本","outputs":"业绩归属明细、考核结果、奖金模拟及人工复核差异","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：审批规则版本及归属调整，复核异常和争议，签认正式结果；不能确定时挂起争议项，不自动发薪。 程序/规则：读取批准的关系及参数、计算业绩分配和模拟奖金、保留历史口径；重算与差异清单为建议控制，需验证实际功能。 分析模型：核心核算无需概率模型；可选异常检测不能改写结果。 大模型：建议解释核算差异并引用规则条款，不创造奖金公式。 Agent：可建议整理争议材料并发起待审事项，不能批准规则或核算结果。","manualCheck":"审批规则版本及归属调整，复核异常和争议，签认正式结果；不能确定时挂起争议项，不自动发薪。","before":"销售人与管户人可能不一致，多渠道和多层级归属及考核口径需要核对，个性化分行考核难直接复用总行规则。","after":"案例材料按客户或账户维度接入业绩分配关系、配置参数并查看核算结果；新版提到奖金模拟，正式核算确认与发薪仍需授权人工和专业系统。","feedback":"“我希望每笔业绩算给谁、按哪版规则计算都能查清，争议处理不再靠反复找人对表。”","metrics":[{"dimension":"效率","nature":"V00","text":"客户、账户等维度可统一分配核算，需补单周期核算人时、争议件处理时间及重算范围。"},{"dimension":"质量/风险","nature":"V00","text":"案例材料区分会计与考核2种口径，需补归属正确率、差异复核率与规则版本可追溯率。"},{"dimension":"经营/管理","nature":"V00","text":"支持分支行差异化考核和奖金模拟，需补争议减少量与结算准时率，不能声称已提升营销转化。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"分配关系、规则参数、考核查询与部分奖金模拟；实际生效流程待核；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"不代替考核制度审批、正式评价与发薪，不自动调整客户归属","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]},{"id":"BA01-P04","name":"报告与指标服务","desc":"提供统一指标查询、经营报告和管理材料支持。","scenes":[{"id":"BA01-P04-S01","title":"授权范围内业务自助取数","definition":"业务分析人员在临时取数和条件变化时使用受控数据集自助查询与加工，获得满足业务口径及导出权限的结果。","decision":"AI-L1","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["运营提效","客户与员工体验"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"业务分析人员、数字化营销岗、产品经理","trigger":"临时分析、条件变更或周期数据需求","task":"在已有授权与口径下灵活获得临时分析结果","dataScope":"授权数据表、字段及码值、指标口径、查询条件与导出权限","outputs":"查询表、分析数据集、受控导出结果","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：确认用途、口径与结果，敏感数据先走授权；缺字段或超权限时停止查询并提交相关场景，不绕过审批。 程序/规则：执行数据集与行列权限、查询加工和导出控制；结果依据已维护字段定义。 分析模型：当前不需要预测模型。 大模型：建议把业务问题转换为待确认的指标与过滤条件，取数执行必须受控。 Agent：可建议编排查询和依据展示；不能自行增权、任意生成SQL直连生产或导出数据。","manualCheck":"确认用途、口径与结果，敏感数据先走授权；缺字段或超权限时停止查询并提交相关场景，不绕过审批。","before":"临时取数依赖跨部门申请与反复沟通，条件变化后需要重新协调，业务人员难以自行调整。","after":"在已授权的数据集上自助查询和加工，条件变化可自行调整；首次授权、敏感审批和导出控制仍按制度执行。","feedback":"“我希望在已有权限内自己调整取数条件，同时清楚知道每个字段的口径和哪些数据不能导出。”","metrics":[{"dimension":"效率","nature":"V00","text":"在已有授权下减少重复沟通，需补同类查询前后周期与单次准备人时。"},{"dimension":"质量/风险","nature":"V00","text":"前置查看与导出权限，需补越权阻断率、结果对账通过率及用途复核记录。"},{"dimension":"经营/管理","nature":"V00","text":"提高临时分析需求响应能力，需补需求满足率和科技取数工单变化，不能按数据集数折算收益。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"BI授权查询和加工；自然语言问数、实时网关和任意SQL未证实；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"不把自助等同无审批，600余取数次数是平台范围而非本卡AI调用量","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]}]},{"id":"BA02","mark":"零","name":"零售金融","desc":"围绕个人客户和零售客群开展分层、存量经营和营销活动管理。","sections":[{"id":"BA02-P01","name":"客户分层与客群经营","desc":"识别目标客户并形成可持续分析和经营的客群。","scenes":[{"id":"BA02-P01-S01","title":"重点客群分层与生命周期经营","definition":"零售客群经营人员在周期经营分析中，对重点客群进行画像、分层和生命周期分析，形成差异化经营策略与重点关注清单。","decision":"AI-L1","maturity":"M2 方案验证","version":"v1.0","flagship":false,"gateway":false,"values":["经营增长","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"planned","D04":"planned"},"role":"零售业务管理人员、客群经营人员、信用卡与个人金融条线人员","trigger":"月度客群经营分析、营销活动策划、客户留存与资源配置前","task":"统一客群口径→分析画像与资产结构→完成RFM或生命周期分层→识别资金流动与增长质量→形成经营策略和重点客群清单","dataScope":"客户基础属性、AUM与活期资产、薪资与交易、产品持有、营销触达、资金流入流出、生命周期与客户等级。","outputs":"客群画像、分层结果、生命周期分布、资金流动分析、增长质量判断、经营策略和重点关注清单。","collaboration":"当前以BI指标、模型和看板为主；后续可由Dora或联合Agent完成归因、策略草稿与任务协同。","manualCheck":"确认客群定义、分层规则、策略适用范围以及营销名单和资源配置。","before":"信用卡、代发、低AUM等客群数据分散在不同报表中，分析多按产品临时开展，分层口径、生命周期判断和经营策略难以持续复用。","after":"BI看板统一呈现客群规模、资产、交易、产品持有和生命周期变化，支持RFM、资金流向与营销归因分析；经营人员确认分层口径和策略。","feedback":"“我能用同一套方法看清不同重点客群处在哪个阶段、为什么变化，以及下一步该把资源投向哪里。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充单个客群分析的人时基线、更新频率和目标周期。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充分层口径一致率、数据完整率和策略人工复核要求。"},{"dimension":"经营/管理","nature":"V03 实测参考","text":"作品材料已识别非价值贷记卡客户中快捷支付为零的客户约占80%，可作为重点促活客群线索。"}],"quantBasis":"昆山BI大赛三份客群作品；80%为材料中的客群现状，不等于经营成效。","scope":"已覆盖信用卡非价值客群、企业代发客群和AUM 5万以下客群的BI分析样例；尚未形成统一客群模型和跨客群任务闭环。","boundary":"产品或客群名称只是分析对象，不单独构成新场景；营销触达和权益配置由业务人员确认。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"暂无","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B03","B04","B05"]}]},{"id":"BA02-P02","name":"存量客户经营","desc":"围绕存量客户分析价值、需求、流失和经营机会。","scenes":[{"id":"BA02-P02-S01","title":"零售客户洞察与下一最佳行动","definition":"零售客户经理、客群经营人员在见客前、沟通中、营销后环节，CRM内统一呈现客户画像、风险、产品缺口和下一最佳行动，并生成可解释的话术建议。","decision":"AI-L2","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"零售客户经理、客群经营人员","trigger":"见客前、沟通中、营销后；业务对象或触发范围：零售客户经理服务的存量客户","task":"在CRM汇聚客户信息→生成画像、风险和产品缺口→对话解释数据依据→给出话术与行动建议→跟踪动作效果","dataScope":"在CRM聚合客户、产品和接触数据，执行产品资格与适当性规则。","outputs":"调用画像、规则、模型和知识库，跟踪营销动作效果。","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：核实资金用途和真实意愿，确认适当性与联系授权后沟通；资料异常先核查，不因动账直接营销或风险定性。 程序/规则：关联管户权限、产品到期与资产信息，按批准规则筛选动账并展示明细。 分析模型：可建议机会排序，案例材料未证明下一最佳行动评分模型。 大模型：建议生成客户摘要和沟通提纲，结论引用事实。 Agent：可建议组织访前材料，人工确认后才进入CRM动作，不自动联系客户。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"判断客户真实需求，选择是否采纳建议并完成客户沟通。","before":"客户经理在多个页面查客户资产、产品和接触记录，单客分析慢，营销时机依靠经验。","after":"CRM内统一呈现客户画像、风险、产品缺口和下一最佳行动，并生成可解释的话术建议。","feedback":"“我见客前3分钟就能掌握客户重点，每天可以服务更多客户，沟通也更有针对性。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"单客分析由30分钟压缩至3分钟，效率提升90%，每天可多服务2—3名客户。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"产品资格和适当性规则校验覆盖率保持100%，建议依据可追溯率达到95%以上。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"营销转化率提升30%以上，建议试点将有效行动回录率提升至90%以上。"}],"quantBasis":"Excel“独立场景库”RW-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。 本轮案例补充范围：客户资产/到期/动账信息展示，通联过程部分可查；AI评分、自动触达与统一回录未证实；不据此升级整卡成熟度或AI实施状态。","boundary":"高风险动作人工确认；营销建议符合适当性与消费者保护要求；答案可追溯到数据依据。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03","B04","B05"]},{"id":"BA02-P02-S02","title":"零售客户流失预测与个性化维护工单","definition":"客户经理、客户运营人员在日常维护、流失干预环节，系统提前识别高危客户与关键因子，自动生成维护工单、建议话术并跟踪结果。","decision":"AI-L3","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"partial"},"role":"客户经理、客户运营人员","trigger":"日常维护、流失干预；业务对象或触发范围：AUM、交易或互动出现下降信号的零售客户","task":"构建客户流失特征→预测流失概率和高危因子→生成维护策略与工单→客户经理执行→回录结果","dataScope":"监测AUM和交易变化，生成工单、控制联系频次并记录处置。","outputs":"按风险触发工单，调用策略服务并跟踪维护结果。","collaboration":"DORA主承接：原因解释、建议和工单编排。模型服务：流失预测。CRM：客户联系与记录。人工：维护执行。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认高危客户，执行维护并记录真实反馈。","before":"客户流失通常在AUM明显下降后才被发现，客户经理还要手工排查原因和整理维护名单。","after":"系统提前识别高危客户与关键因子，自动生成维护工单、建议话术并跟踪结果。","feedback":"“我能在客户真正流失前收到有原因的提醒，并按优先级完成维护。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"高危客户筛选与工单准备时间减少60%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"高危客户识别召回率达到80%以上，联系频次合规率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"试验组客户流失率较对照组下降10%以上，维护结果回录率达到90%以上。"}],"quantBasis":"Excel“独立场景库”RW-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。","boundary":"明确流失标签和观察期；控制过度联系；以对照实验验证增量效果。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03","B04","B05"]},{"id":"BA02-P02-S03","title":"闲置资金识别与存款产品智能配置","definition":"财富顾问、零售客户经理在资金识别、产品匹配、营销环节，系统识别稳定闲置资金、计算可配置金额并按产品规则生成客户清单和配置建议。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"财富顾问、零售客户经理","trigger":"资金识别、产品匹配、营销；业务对象或触发范围：账户存在可用或闲置资金的零售客户","task":"识别资金留存与波动特征→计算可配置资金→匹配存款期限和产品→生成客户清单与配置建议→跟踪转化","dataScope":"计算可配置资金，按期限、金额和产品规则匹配存款方案。","outputs":"定时筛选客户，调用产品规则和模型，派发营销任务。","collaboration":"DORA主承接：解释、话术和任务编排。数据/模型服务：资金识别。产品系统：规则与交易。人工：适当性与沟通。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"核验客户需求和产品适当性，决定是否提出配置建议。","before":"客户经理手工查账户余额和资金变化，再凭经验匹配存款期限与产品。","after":"系统识别稳定闲置资金、计算可配置金额并按产品规则生成客户清单和配置建议。","feedback":"“我能及时发现真正可配置的资金，并用清楚的依据和客户讨论合适期限。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"客户筛选与方案准备时间减少60%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"产品资格与适当性校验覆盖率保持100%，临时大额资金误判率控制在10%以内。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"目标客户存款转化率提升15%以上，资金30日留存率提升5%以上。"}],"quantBasis":"Excel“独立场景库”RW-04。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"遵守产品适当性和营销授权；区分临时大额流入与稳定闲置资金。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B04"]},{"id":"BA02-P02-S04","title":"理财客户与产品经营分析","definition":"财富管理人员统一分析理财客户、产品、渠道和风险，形成符合适当性要求的经营机会与产品运营建议。","decision":"AI-L3","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["经营增长","管理决策","风险合规"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"planned"},"role":"财富管理人员、产品经理、网点负责人、理财经理","trigger":"理财日常经营、产品发行与到期、客户资金变动、营销活动和周期复盘","task":"汇聚客户—产品—渠道—风险数据→分析结构→识别机会和风险→人工确认→复盘转化","dataScope":"AUM、理财规模与收益、客户分层、产品生命周期、渠道销量、营销转化、适当性和风险指标。","outputs":"理财经营全景、客户结构、产品分析、渠道效能、到期资金机会和合规清单。","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：确认统计口径、客户授权和频次，复核成交归属及截图矛盾，决定接续策略；分母冲突先停用争议比例。 程序/规则：关联名单与各波次结果、计算漏斗和交易汇总；不把重复触达或交易笔数误作去重客户。 分析模型：可另做对照或增量归因，截图无因果模型证据；80%置信度方法未说明。 大模型：建议总结漏斗和数据异常，不自行解释为AI增量收益。 Agent：可建议整理复盘与待核问题；外呼短信和跟进下发均需授权与人工确认，不能自动批量触达。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"确认客户需求、风险承受能力、产品适配、营销名单、触达内容和最终推荐。","before":"管理层、产品经理和理财经理分别查看不同报表，难把客户结构、产品生命周期、渠道转化和风险放在一起判断。","after":"系统形成战略、运营和执行多角色视图，联动分析客户、产品、渠道和风险，输出经人工审核的经营建议。","feedback":"“我能同时看见客户需要什么、产品表现怎样和哪些合规条件要先核对，再决定如何服务。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"集中分析客户、产品、渠道和风险4类数据，取数和材料准备时长目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"经营建议前校验适当性和风险条件，规则覆盖率和拦截率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"服务战略、运营、执行3类角色，渗透率、转化率和中收目标待确认。"}],"scope":"已有理财规模、客户、产品、渠道和风险分析方案；适当性联动和结果回录仍需验证。 本轮案例补充范围：1张2024年活动复盘截图的已核信息，只补理财卡的渠道复盘模块，不是运行Demo或外呼系统验收；不据此升级整卡成熟度或AI实施状态。","boundary":"不自动推荐或销售理财产品，必须遵守适当性、消费者保护、双录和联系授权。","assets":{"方案 PPT":"已有","看板 Demo":"材料含原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04","B05"]}]},{"id":"BA02-P03","name":"营销活动管理","desc":"支持营销名单、触达、转化和活动复盘。","scenes":[{"id":"BA02-P03-S01","title":"潜在非存客户营销倾向预测","definition":"营销管理人员、客户经理在营销名单筛选环节，客户按营销成功概率排序，结合规则控制触达频次并提供产品匹配理由与差异化话术。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"营销管理人员、客户经理","trigger":"营销名单筛选；业务对象或触发范围：未持有存款或待营销的零售客户","task":"汇集基础、资产交易与历史营销数据→预测营销成功概率→排序筛选→差异化触达→回录结果校准模型","dataScope":"准备客户特征、控制触达规则、生成名单和统计转化效果。","outputs":"编排名单评分、分配、触达提醒和效果回流。","collaboration":"DORA主承接：话术和营销Agent。外部模型服务：倾向评分。CRM：名单与接触记录。人工：营销执行。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"审核营销名单，执行合规触达并回录结果。","before":"非存客户名单主要按经验筛选并批量外呼，无效触达多且容易引发反感。","after":"客户按营销成功概率排序，结合规则控制触达频次并提供产品匹配理由与差异化话术。","feedback":"“我会优先联系更有需求的客户，少打无效电话，也更容易解释为什么推荐这个产品。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"低倾向客户触达量减少30%以上，名单准备时间减少50%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"模型准确率达到75%以上；建议试点将联系授权与频次校验覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"目标客群转化率提升15%以上，客户投诉率不高于现有基线。"}],"quantBasis":"Excel“独立场景库”RW-03。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"需建立真实标签和基线；模型准确率之外还应评估转化提升、成本和客户投诉。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B04"]},{"id":"BA02-P03-S02","title":"存款积分动态管理与权益精准运营","definition":"权益运营人员、零售客户在客户存续与活动运营环节，积分与权益按存款稳定性动态管理，客户偏好驱动礼品和活动匹配，并持续评估留存效果。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"权益运营人员、零售客户","trigger":"客户存续与活动运营；业务对象或触发范围：持有存款和积分权益的零售客户","task":"分析存款存续、波动和AUM→动态调整积分系数与权益等级→识别过期/沉睡积分→匹配活动与礼品→评估留存和参与","dataScope":"计算动态积分、权益等级、积分到期和活动资格。","outputs":"编排客户筛选、权益推荐、邀约和效果评估。","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：核实参与分母和成本归因，审核权益规则、公平性及预算，不因年龄偏好直接自动投放。 程序/规则：关联权益发放使用与资产变化，计算响应及成本比；增量因果需要另设对照。 分析模型：可建议偏好或增量效果模型，当前只有BI分群观察。 大模型：建议生成复盘草稿并提示分母和归因限制。 Agent：可建议编排复盘材料，不自动改变积分政策或发放权益。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"审批积分政策、活动预算和客户沟通方案。","before":"积分倍率和礼品供给相对静态，活动主要面向大客群统一投放，沉睡积分和偏好难利用。","after":"积分与权益按存款稳定性动态管理，客户偏好驱动礼品和活动匹配，并持续评估留存效果。","feedback":"“我收到的权益和活动更贴合自己的需要，也能清楚知道积分什么时候使用最合适。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"活动客群筛选与权益匹配工作量减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"积分规则计算准确率达到100%，客户授权与公平性检查覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"活动点击或兑换参与度达到现有水平的2—3倍；建议试点将稳定存款留存率提升5%以上。"}],"quantBasis":"Excel“独立场景库”RW-05。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。 本轮案例补充范围：单活动BI复盘；未证明积分动态规则、自动推荐和触达闭环；不据此升级整卡成熟度或AI实施状态。","boundary":"积分规则需公开一致并通过合规审查；避免不透明或歧视性差异定价；预期效果需实测。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02","B05"]},{"id":"BA02-P03-S03","title":"出行场景智能规划与金融服务","definition":"零售客户、客户服务人员在额度、规划、结算、评价环节，对话式服务统一编排行程、餐饮住宿、专属额度、支付与评价，异常环节转人工处理。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效","客户与员工体验"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"零售客户、客户服务人员","trigger":"额度、规划、结算、评价；业务对象或触发范围：中年及养老客群的出行消费需求","task":"基于客户画像评估专属额度→对话生成行程与消费方案→一键结算→评价服务商→运营优质供给","dataScope":"执行额度、支付、结算、商户资格和订单规则。","outputs":"协调额度、出行服务、支付和评价工具完成全流程。","collaboration":"DORA主承接：对话规划和服务Agent。信贷/支付/商户平台：额度、交易和订单。推荐服务：排序。人工：审批与异常处置。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认授信与服务选择，处理行程变化、投诉和异常交易。","before":"额度、行程规划、商户服务和支付分散，客户需要在多个入口自行比较与组合。","after":"对话式服务统一编排行程、餐饮住宿、专属额度、支付与评价，异常环节转人工处理。","feedback":"“我可以在一个入口完成出行规划和支付，方案变化时也能快速调整。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"单次行程规划与比选时间减少60%以上，订单流程一次完成率达到85%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"客户满意度达到4.8分，授信、支付和异常交易人工控制覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"覆盖100万以上客户、带动手机银行月活提升25%、接入500家以上合作商户。"}],"quantBasis":"Excel“独立场景库”RW-07。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"涉及授信、旅游服务商、支付和推荐的多方合规；需验证合作供给、责任边界和量化目标。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]}]},{"id":"BA03","mark":"公","name":"公司金融","desc":"覆盖企业财资服务（CBS）、公司客户拓展、授信协同和存量经营；区分对客服务与银行行内管理。","sections":[{"id":"BA03-P04","name":"企业财资服务（财资大管家 / CBS）","desc":"银行为企业客户提供账户收支、融资额度与到期统筹服务，由企业负责人确认资金安排，不属于银行内部财务。","scenes":[{"decision":"AI-L2","maturity":"待核实 · 已有BI方案，AI为建议增强","version":"v0.2","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["运营提效","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"done","D04":"planned"},"role":"企业客户的财务/资金负责人、获授权企业主；银行公司金融/交易银行团队为服务提供方。","collaboration":"材料为企业财资BI/规则分析。建议C02嵌入企业财资平台：Dora承担授权问数、解释和摘要；专业程序负责权限、统计、提醒与记录，企业负责人确认后续动作。AI尚无部署证据，不默认启用联合Agent。","assets":{"方案 PPT":"已有内部案例材料，未配置公开链接","看板 Demo":"材料含虚拟测试截图，非在线Demo","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B06"],"id":"BA03-P04-S01","title":"企业资金账户与收支监测","definition":"银行通过企业财资服务平台，为企业主及财务人员汇总获授权的跨行账户、余额与收支，帮助企业查看资金分布、核对异动并形成经营判断。","trigger":"企业日常资金盘点、收支核对及经营复盘；小企业主适用范围需结合授权账户和实际需求验证。","task":"企业授权账户→程序汇集余额和交易→按主体、币种与时点汇总→核对异动→企业负责人决定资金安排。","dataScope":"企业管理权限内的单位、时间、币种、银行、账户、余额变化、交易明细、收支与交易排行。","outputs":"企业资金账户全景、收支明细、余额趋势、交易排行与待核异常清单。","manualCheck":"企业确认主体和账户授权、统计口径及异常事实，决定资金用途；银行核验数据服务权限，不代替企业批准资金动作。","before":"企业账户与收支信息分散，财务人员需汇总核对后才能判断资金分布；逐户登录及手工拼表的具体成本仍需访谈核实。","after":"BI与受控程序统一展示授权账户、余额和收支明细；建议叠加AI解释波动与生成摘要，企业财务核实后决定资金动作。","feedback":"“我能在一个视图里看清企业的钱在哪里、怎么流动，发现异常后再核对原始交易。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"统一账户与收支查询，减少重复汇总；查询次数、准备时长和目标周期待企业试点确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"按授权账户追溯交易与余额，辅助核对异常；授权覆盖率、匹配错误率及复核范围待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"资金分布与变化支持企业资金安排；闲置资金识别、资金集中率和服务采纳目标待确认。"}],"quantBasis":"KH-NAV-01 M105 chunk10为功能证据，截图为虚拟测试数据；未提供可靠效率/资金收益数字，三项V00，不外推生产成效。","scope":"材料支持账户、资金余额、收支及排行等BI分析；AI解释、自动提醒和业务执行均未被证实。","boundary":"公司金融对客企业财资服务（CBS），不是银行内部财务/ALM。不得跨企业越权汇总或跨币种直接相加；不执行资金划拨、支付或投资。"},{"decision":"AI-L2","maturity":"待核实 · 已有BI方案，AI为建议增强","version":"v0.2","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["运营提效","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"done","D04":"planned"},"role":"企业客户的财务/资金负责人、获授权企业主；银行公司金融/交易银行团队为服务提供方。","collaboration":"材料为企业财资BI/规则分析。建议C02嵌入企业财资平台：Dora承担授权问数、解释和摘要；专业程序负责权限、统计、提醒与记录，企业负责人确认后续动作。AI尚无部署证据，不默认启用联合Agent。","assets":{"方案 PPT":"已有内部案例材料，未配置公开链接","看板 Demo":"材料含虚拟测试截图，非在线Demo","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B06"],"id":"BA03-P04-S02","title":"企业融资额度与到期偿付统筹","definition":"银行通过企业财资服务平台，为企业主及资金管理人员汇总融资余额、授信额度使用与债务到期信息，辅助企业统筹续作和偿付安排。","trigger":"企业融资台账复盘、额度使用核对与债务到期前的资金安排；小企业主适用范围需结合合同、账户与权限确认。","task":"企业核对合同和额度→程序汇总余额、使用与到期日→查看期限集中→形成统筹摘要→企业确认续作或偿付计划。","dataScope":"融资金额/余额、期限、债权人、融资类别、企业/子公司、授信额度使用、到期日及偿付信息。","outputs":"企业融资全景、额度使用与债务到期清单、偿付压力摘要和人工确认事项。","manualCheck":"企业负责人核实合同、额度和到期日，决定融资及偿付；银行另按信贷流程审批，提醒接收人和时间须企业确认。","before":"企业融资余额、额度与到期日需从多份台账核对，统筹融资和偿付依赖人工整理；具体工时与遗漏率待访谈确认。","after":"BI与程序按主体、债权人和期限展示融资、额度及到期事实；建议AI解释到期集中并编排获批提醒，企业负责人确认后续安排。","feedback":"“我能提前看清哪些融资将到期、额度用了多少，安排偿付时更有依据。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"统一融资、额度和到期信息，减少台账整理；准备时长、核对频次及目标周期待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"融资期限与额度可追溯，辅助识别遗漏和到期集中；合同匹配率与到期核查目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"债务到期全景支持企业融资与偿付统筹；续作及时率、额度利用和观察范围待确认。"}],"quantBasis":"KH-NAV-01 M105 chunks11/12/14为功能证据，截图为虚拟测试数据；验收图片未核读，不使用V04或臆造节约比例。","scope":"材料支持融资、期限、债权人、额度使用和到期还款分析；提醒、预测和Agent为建议增强，并非既有AI事实。","boundary":"企业侧融资统筹，不是银行授信审查或银行自身ALM。不自动申请授信、续贷或付款；无现金计划与验证时只列到期事实，不预测偿付缺口。"}]},{"id":"BA03-P01","name":"客户拓展与经营","desc":"支持客户发现、访前准备、拜访和后续跟进。","scenes":[{"id":"BA03-P01-S01","title":"商票贴现链式获客与再贴现服务","definition":"票据业务人员、公司客户经理在商票贴现、再贴现、链式获客环节，统一核验票据和政策规则，关联上下游客户线索并生成材料清单，人工完成真实性与授信审批。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"票据业务人员、公司客户经理","trigger":"商票贴现、再贴现、链式获客；业务对象或触发范围：核心企业及产业链上下游中小微企业","task":"归集商票贴现需求→核验贸易背景→匹配再贴现政策→链式服务上下游客户→跟踪收益与客户转化","dataScope":"归集商票数据，校验再贴现资格、贸易背景、额度和业务规则。","outputs":"协调票据、CRM、政策规则和客户线索服务。","collaboration":"DORA辅助承接：政策问答、材料摘要和服务编排。票据系统与核心系统：交易和账务。风控服务：资格与风险校验。人工：审批。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认贸易真实性、政策资格与授信风险；完成票据业务审批。","before":"票据需求、贸易背景、政策资格和产业链线索分散，业务人员逐项核验和寻找客户。","after":"统一核验票据和政策规则，关联上下游客户线索并生成材料清单，人工完成真实性与授信审批。","feedback":"“我能更快判断一笔商票是否符合政策，也能顺着核心企业找到值得跟进的上下游客户。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"单笔资格核验与材料准备时间减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"贸易背景和再贴现必核项覆盖率达到100%，材料缺项率下降30%以上。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"有效产业链客户线索增加20%以上，线索转化率提升10%以上。"}],"quantBasis":"Excel“独立场景库”CP-04。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"需完善贸易真实性核验、票据合规、再贴现资格和资金用途控制。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA03-P01-S02","title":"贴现业务经营分析与目标督导","definition":"公司业务管理人员按周期分析贴现规模、客户和收入表现，定位机构与客户经理差距并形成目标督导事项。","decision":"AI-L1","maturity":"M2 方案验证","version":"v1.0","flagship":false,"gateway":false,"values":["管理决策","运营提效","经营增长"],"abilities":{"D01":"done","D02":"partial","D03":"planned","D04":"planned"},"role":"公司业务管理人员、支行管理人员、票据业务人员和客户经理","trigger":"日常经营监测、月度复盘、目标制定和机构督导时","task":"汇总贴现规模、户数和利息收入→按机构与客户经理比较→分析趋势和差距→设定目标→形成督导与协同事项","dataScope":"贴现规模、贴现户数、贴现利息收入、机构和客户经理业绩、历史趋势与目标。","outputs":"经营看板、趋势分析、机构与客户经理排名、目标差距和督导事项。","collaboration":"当前以BI指标和看板为主；后续可由Dora生成异动归因、经营摘要和督导任务草稿。","manualCheck":"确认经营目标、机构差距、考核口径和督导要求。","before":"贴现规模、户数、收入和人员业绩分散在不同统计表中，经营复盘与目标督导依赖人工汇总和经验判断。","after":"BI看板统一展示核心指标、趋势、机构和客户经理表现，管理人员据此确认目标、差距和督导重点。","feedback":"“我能快速看清贴现业务增长来自哪里、哪些机构需要跟进，不再临时拼表后才开始讨论。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充贴现经营材料准备时长、更新频率和目标周期。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充核心指标口径一致率和异常数据复核要求。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充目标达成改善、落后机构跟进率或贴现客户增长指标。"}],"quantBasis":"昆山BI大赛贴现业务分析作品未提供可验证成效数字。","scope":"已覆盖贴现规模、户数、利息收入及机构和客户经理分析；目标流转和执行反馈闭环尚待补充。","boundary":"不替代商票贸易背景核验、再贴现资格判断和单笔业务审批。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"暂无","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B03","B04"]}]},{"id":"BA03-P02","name":"授信协同","desc":"连接客户经营与授信流程中的材料和分析任务。","scenes":[{"id":"BA03-P02-S01","title":"对公客户360全景与风险智能分析","definition":"对公客户经理、授信审查与贷后人员在贷前调查、授信审查、贷后监测环节，系统自动汇聚客户全景、识别经营与风险异常并生成有证据的分析简报，人工只核验关键事实和结论。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"对公客户经理、授信审查与贷后人员","trigger":"贷前调查、授信审查、贷后监测；业务对象或触发范围：对公客户；新授信、续作或贷后检查触发","task":"汇聚行内外信息→形成客户全景→经营与风险评分→生成分析简报→人工复核","dataScope":"按客户统一标识汇集行内数据；执行字段校验、规则评分和报告模板组装。","outputs":"调用画像、评分、检索和报告工具，生成待复核简报。","collaboration":"DORA主承接：对话、知识检索、摘要生成、工具编排。外部服务：客户360与评分模型。信贷系统：审批与留痕。人工：最终判断。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"核验客户范围与异常信息；形成最终授信、续作或贷后判断。","before":"客户经理在多个系统和外部渠道逐项查数、拼表，再凭经验形成客户判断。","after":"系统自动汇聚客户全景、识别经营与风险异常并生成有证据的分析简报，人工只核验关键事实和结论。","feedback":"“我不用再花大量时间跨系统拼材料，见客户或审查前就能快速看清经营机会和风险依据。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"单户报告准备由2—4小时压缩至1—2小时，成熟环节可由1—2天缩短至分钟级，整体效率提升60%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"风险信息覆盖率达到95%以上，并对异常结论保留来源和证据。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"标准化简报覆盖90%以上目标客户，人工采纳或修订后使用率达到80%以上。"}],"quantBasis":"Excel“独立场景库”CP-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"建立客户统一标识；外部数据合规接入；评分与结论可解释；报告仅作辅助。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA03-P02-S02","title":"绿色企业与项目智能识别及认定材料生成","definition":"绿色金融客户经理、认定审核人员在营销拓客、贷前调查、绿色认定环节，系统解析项目材料、匹配绿色目录与负面清单，生成带条款依据的认定建议和申报初稿。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"绿色金融客户经理、认定审核人员","trigger":"营销拓客、贷前调查、绿色认定；业务对象或触发范围：拟营销或申报绿色信贷的企业与项目","task":"解析企业与项目材料→检索绿色目录和政策→规则与大模型联合判定→输出认定依据、核查清单和材料初稿→人工确认","dataScope":"校验材料完整性，执行绿色目录、负面清单和申报规则。","outputs":"调用OCR、外部数据、知识库和规则服务，编排识绿流程。","collaboration":"DORA主承接：RAG、解释、材料生成和Agent编排。外部服务：OCR、ESG/环保数据和语义模型。信贷系统：申报与审批。人工：认定。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认绿色属性与边界项目；审核认定材料并承担认定责任。","before":"客户经理人工翻查绿色目录、政策和环保材料，识绿慢且不同人员判断口径不一。","after":"系统解析项目材料、匹配绿色目录与负面清单，生成带条款依据的认定建议和申报初稿。","feedback":"“我能在几分钟内拿到有政策出处的识绿建议，边界项目也清楚知道需要补什么证据。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"绿色识别由约2小时缩短至5分钟，效率提升95%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"识别一致性由约70%提升至95%以上，边界项目仍保持100%人工复核。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"绿色项目认定材料一次性完整率达到90%以上，识绿线索转化提升15%以上。"}],"quantBasis":"Excel“独立场景库”CP-05。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"必须引用制度条款和材料原文；边界项目人工复核；第三方ESG、环保数据需验证时效与授权。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]},{"id":"BA03-P03","name":"综合经营与存量维护","desc":"分析客户综合价值并推动存量客户持续经营。","scenes":[{"id":"BA03-P03-S01","title":"对公业务经营全景与结构分析","definition":"对公条线管理者以统一经营视图穿透公司、国际、投行和票据业务，识别增长与结构问题并推动策略复盘。","decision":"AI-L2","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["管理决策","经营增长","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"对公条线管理者、机构负责人、公司客户经理、产品经理","trigger":"日常经营监测、月季经营分析、专项策略研讨和机构复盘","task":"汇聚跨板块指标→查看规模与营收结构→下钻机构和客户→识别问题→形成策略→复盘效果","dataScope":"对公存贷款、外币业务、票据、投行撮合、中间业务收入、客户、产品和人效。","outputs":"对公经营全景、板块结构与趋势、机构与人员排名、重点客户明细和策略复盘。","collaboration":"Dora跨看板问数、解释结构变化并生成经营摘要；BI保持指标事实与下钻；经营策略由条线人员确认。","manualCheck":"确认指标口径、异常原因、经营策略、客户名单和机构督导动作。","before":"经营会前需跨多个看板和表格汇总板块数据，发现波动后还要人工定位到机构、客户经理和客户。","after":"系统提供4个专业板块加1个整体视图，支持指标到明细穿透并形成结构变化与行动建议。","feedback":"“我能从对公全局一路下钻到具体机构和客户，不再靠拼表判断增长来自哪里。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"统一4个专业板块和1个整体视图，经营会材料准备时长目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"支持从一级机构下钻至客户，口径一致率和异常复核率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"同时观察规模、营收、客户、产品和人效5类维度，策略执行指标待确认。"}],"scope":"已有公司、国际、投行、票据和整体经营看板；AI归因和跨系统闭环仍需验证。","boundary":"服务条线整体经营，不替代单客360、单笔授信审查或信贷投放管理。","assets":{"方案 PPT":"已有","看板 Demo":"材料含多主题截图","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]}]}]},{"id":"BA04","mark":"普","name":"普惠小微与三农","desc":"覆盖获客、调查、授信、贷后和风险处置。","sections":[{"id":"BA04-P01","name":"获客与调查","desc":"识别普惠、小微和三农客户并开展业务调查。","scenes":[{"id":"BA04-P01-S01","title":"名单制营销客户分层与策略匹配","definition":"对公营销人员、客户经理在名单导入、分层触达、结果回录环节，名单自动增强和分层，按成功概率分配差异化任务、话术与频次，并用回录结果持续校准。","decision":"AI-L3","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["经营增长","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"partial"},"role":"对公营销人员、客户经理","trigger":"名单导入、分层触达、结果回录；业务对象或触发范围：政采贷、绿色金融、科技金融等外部或行内营销名单","task":"名单增强→成功概率评分与分层→自动分配和差异化触达→结果回录→A/B测试与模型迭代","dataScope":"导入名单、校验数据、控制联系频次、分配任务并统计A/B效果。","outputs":"完成名单增强、评分、任务分配、提醒和结果回流的流程编排。","collaboration":"DORA主承接：Agent流程、话术与原因归纳。外部模型服务：倾向评分。CRM：名单、任务与客户接触记录。人工：营销执行。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"审核营销名单与策略；执行客户沟通并回录真实结果。","before":"名单导入后按统一节奏逐户联系，客户优先级不清，失败原因也很少沉淀。","after":"名单自动增强和分层，按成功概率分配差异化任务、话术与频次，并用回录结果持续校准。","feedback":"“我可以先联系最有可能成交的客户，也能知道该用什么切入点，低效电话明显减少。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"低潜客户无效外呼减少50%以上，名单处理由数天缩短至半天。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"营销结果有效回录率达到90%以上，联系频次合规覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"模型分组转化率提升30%以上，并形成至少1套可持续迭代的A/B策略。"}],"quantBasis":"Excel“独立场景库”CP-03。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。","boundary":"确保营销授权与联系频次合规；建立回录质量机制；用真实A/B结果校准预期。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03","B04"]},{"id":"BA04-P01-S02","title":"网格客户覆盖与走访经营","definition":"网格管理人员基于客户建档、产品覆盖和走访记录识别优先对象，经人工确认后组织走访并跟踪转化。","decision":"AI-L3","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["经营增长","运营提效","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"普惠金融管理人员、支行负责人、网格员、客户经理","trigger":"网格建档后、周期走访计划制定或业务覆盖率偏低时","task":"整合网格档案→统一标签与覆盖口径→评估潜力→生成走访顺序→人工确认→回录复盘","dataScope":"网格建档、客户信息、产品持有、资产、业务覆盖、标签、走访频次和结果。","outputs":"网格覆盖地图、未覆盖与高潜名单、走访计划、标签变化和机构转化复盘。","collaboration":"Dora解释潜力评分并生成走访准备；CRM/网格系统维护授权、任务和回录；客户经理决定实际走访。","manualCheck":"确认联系授权、走访名单、优先级、拜访内容、回录质量和后续服务。","before":"客户经理按熟悉程度或临时任务走访，未覆盖客户、业务潜力和历史触达分散在不同台账中。","after":"系统按网格呈现建档、覆盖、标签和走访情况，生成可解释的高潜名单和走访优先级，回录后复盘转化。","feedback":"“我知道这个网格还有谁没覆盖、为什么值得先去，也能看到每次走访是否带来实际变化。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"对超过1.2万户建档客户统一排序，名单准备和无效走访下降目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"统一4类客户标签和多项覆盖口径，档案有效率和授权合规率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"现状理财渗透率2.17%、收单覆盖率32.68%，实际提升需试点验证。"}],"scope":"已有网格建档、覆盖分析、标签与潜力评分方案；自动任务和转化实验仍需验证。","boundary":"网格覆盖不等于强制营销，不得绕过客户授权、隐私保护和联系频次要求。","assets":{"方案 PPT":"已有","看板 Demo":"材料含原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]}]},{"id":"BA04-P03","name":"贷后与风险处置","desc":"跟踪贷后经营与风险变化，支持问题识别和处置。","scenes":[{"id":"BA04-P03-S01","title":"存量普惠客户综合价值评估与授信调整建议","definition":"普惠客户经理、授信审批人员在贷后检查、业务续作环节，统一汇总客户价值与风险，给出可解释的额度区间和产品组合建议，再由有权人员审定。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["经营增长","运营提效","风险合规"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"普惠客户经理、授信审批人员","trigger":"贷后检查、业务续作；业务对象或触发范围：进入贷后检查或续作流程的存量普惠客户","task":"汇总行内贡献与外部经营风险→计算成长价值分和风险分→给出提额、增信、压降或退出建议→人工审定","dataScope":"汇总客户贡献、还款、产品覆盖与外部信息；执行授信政策和额度边界规则。","outputs":"在贷后检查或续作触发时调用数据、评分和知识服务，形成待办。","collaboration":"DORA主承接：方案解释、报告生成和任务编排。外部服务：双评分和客户特征。信贷系统：额度审批。人工：审定。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认客户经营事实；审定提额、增信、压降、退出及产品组合。","before":"存量普惠客户的贡献、还款和外部经营信息分散，额度与综合服务调整主要依靠个人经验。","after":"统一汇总客户价值与风险，给出可解释的额度区间和产品组合建议，再由有权人员审定。","feedback":"“我能在一次贷后或续作中同时看到客户价值、风险和可行动建议，决策更有依据。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"单户资料归集与方案准备时间减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"价值与风险标准化评估覆盖率达到90%以上，边界客户人工复核率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"有效额度或产品建议的业务采纳率达到80%以上，存量客户二次经营转化提升10%以上。"}],"quantBasis":"Excel“独立场景库”CP-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"明确评分标签与额度建议的审批边界；外部数据授权；避免把模型建议直接作为授信决定。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA04-P03-S02","title":"贷款客户续贷与流失挽留","definition":"客户经理在贷款到期和流失窗口前识别高意愿、风险可接受的客户，经人工确认后开展续贷或挽留并跟踪结果。","decision":"AI-L3","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["经营增长","运营提效","风险合规"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"普惠与零售信贷管理人员、支行负责人、客户经理","trigger":"贷款到期前、用信下降、未续贷和客户流失信号出现时","task":"监测到期与流失→风险规则筛除→评估续贷意愿→生成名单→人工确认触达→回录复盘","dataScope":"贷款与授信到期、还款、逾期、欠息、征信异动、交易活跃和营销反馈。","outputs":"续贷意愿评分、风险筛除、客户名单、触达建议、工单状态和策略效果。","collaboration":"模型服务完成评分，Dora解释意愿并生成沟通建议；信贷和CRM维护授信、联系与回录。","manualCheck":"确认客户资格、风险状态、联系授权、名单优先级和续贷流程发起。","before":"到期客户靠人工逐户筛查，续贷意愿和风险信号分散，营销动作晚、无效外呼多、结果难回流。","after":"系统提前识别干预窗口，先按逾期和征信规则筛除，再输出可解释的优先名单、触达建议和跟踪工单。","feedback":"“我能在客户离开前收到有风险说明和优先级的名单，把时间放在真正值得跟进的人上。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"洪泽样本涉及828户未续贷客户，名单准备时间和有效触达率目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"先排除近3个月逾期或征信异动客户，误筛率和联系合规率目标待确认。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"续贷率目标不低于15%；材料申报年化挽回约350万元，但复算约53.6万元，口径待确认。"}],"scope":"已有到期、流失、续贷意愿和挽留看板方案；自动工单和效果实验仍需核实。","boundary":"名单不得绕过授信、联系授权、征信和风险筛除；模型分数不构成授信承诺。","assets":{"方案 PPT":"已有","看板 Demo":"材料含原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]}]}]},{"id":"BA05","mark":"市","name":"金融市场、资管与托管","desc":"服务市场研究、组合分析和周期材料生成。","sections":[{"id":"BA05-P01","name":"投研与市场分析","desc":"研究市场变化并形成数据分析和投研材料。","scenes":[{"id":"BA05-P01-S01","title":"信用债投资尽调报告智能生成","definition":"信用债投研人员在投前尽调环节，系统自动抽取关键要素、整合多源信息并生成带引用的尽调初稿，人员补访并形成投资判断。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["运营提效","风险合规"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"信用债投研人员","trigger":"投前尽调；业务对象或触发范围：信用债发行人及投资项目","task":"解析募集说明书和行内外数据→抽取发行人、财务与风险要素→按模板生成报告初稿→标注待补信息→投研人员复核","dataScope":"导入募集说明书和行情数据，执行报告模板、清单和字段校验。","outputs":"调用文档、数据、风险和报告服务，跟踪待补材料。","collaboration":"DORA主承接：文档理解、报告和Agent编排。行情/风控服务：数据与信号。投研系统：项目和审签。人工：投资判断。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"核验发行人信息、补充访谈材料并形成投资判断。","before":"投研人员手工阅读募集说明书并跨平台收集发行人、行情和风险信息，报告初稿耗时数天。","after":"系统自动抽取关键要素、整合多源信息并生成带引用的尽调初稿，人员补访并形成投资判断。","feedback":"“我拿到的是带来源和待补项的报告底稿，可以把主要精力放在核验和投资判断上。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"尽调报告初稿由2—3天压缩至约15分钟。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"关键结论引用覆盖率达到95%以上，发行人核心字段人工复核率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"报告返工轮次减少30%以上，同等人力可覆盖的项目数量提升30%以上。"}],"quantBasis":"Excel“独立场景库”FM-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"确认外部数据许可；每项关键结论需标注来源与时点；不得自动替代投资决策。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]},{"id":"BA05-P02","name":"交易与组合管理","desc":"分析交易和组合的结构、收益与风险变化。","scenes":[{"id":"BA05-P02-S01","title":"全天候策略资产筛选与风险平价配置","definition":"量化投研与组合管理人员在月度资产筛选与权重配置环节，专业量化程序统一执行计算、回测、限额和版本留痕，DORA仅提供操作入口、解释与作业编排。","decision":"AI-L2","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"量化投研与组合管理人员","trigger":"月度资产筛选与权重配置；业务对象或触发范围：海纳财富指数及同类多资产策略","task":"导入收益率数据并校验→动量和反转打分→人工确认候选资产→风险平价配置与限额约束→导出结果并保留版本","dataScope":"执行数据校验、动量/反转计算、风险平价配置、权重上限和版本留痕。","outputs":"可选：编排数据上传、模型运行、人工检查点和作业恢复。","collaboration":"专业量化系统主承接计算。DORA仅适合作为操作入口、解释和作业编排，不应承担核心公式、回测和风险限额计算。人工：参数与投资决策。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认候选资产、参数、风险预算和限额例外。","before":"策略数据校验、因子计算和权重配置主要在Excel中手工完成，易出错且版本难追踪。","after":"专业量化程序统一执行计算、回测、限额和版本留痕，DORA仅提供操作入口、解释与作业编排。","feedback":"“我能快速重复验证同一套参数并追溯每次结果，不再担心手工公式或版本混乱。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"策略验证由1—2天压缩至10分钟以内，效率提升90%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"核心公式和风险限额自动校验覆盖率保持100%，运行结果可复现率达到100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"月度策略迭代次数提升2倍以上，参数或版本差错率下降80%以上。"}],"quantBasis":"Excel“独立场景库”FM-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。","boundary":"模型公式保持唯一事实源；风险限额与400%总权重上限需有权部门确认；运行时计算不依赖生成式AI。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03"]},{"id":"BA05-P02-S02","title":"同业存款集合竞价管理","definition":"金融市场部在日常竞价窗口集中处理分行同业报价申请，依据批准策略确定中标并跟踪履约及警告记录。","decision":"AI-L2","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["管理决策","风险合规"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"done"},"role":"总行金融市场部、分行同业业务人员","trigger":"工作日规定竞价窗口与中标后执行检查","task":"集中收集报价，按资金需求与策略确定中标并约束执行","dataScope":"同业金额利率报价、规模期限、申请时间、资金需求和执行记录","outputs":"竞价申请、汇总候选、中标结果与未执行警告","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：总行金融市场部审定策略和中标结果，核实未执行原因及处分边界；异常报价退回核查。 程序/规则：控制窗口、校验申请、汇总和按批准要素排序；按制度记录警告及申请资格，自动生效边界待核。 分析模型：核心筛选用确定规则即可，优化模型仅可试算参考。 大模型：建议解释报价差异和异常，不推荐未经批准交易。 Agent：可建议整理审阅包与执行提醒，不自动发布中标或成交指令。","manualCheck":"总行金融市场部审定策略和中标结果，核实未执行原因及处分边界；异常报价退回核查。","before":"分行分散争取同业存款可能引发价格竞争，资金需求和定价缺少统一协调，需总行集中管理。","after":"案例材料由分行收集报价并提交申请，总行按价格、规模、期限和时间等要素确定中标，对中标未执行分行记录警告及申请约束。","feedback":"“我希望各分行报价能在同一窗口比较，中标和未执行处理都有一致规则可查。”","metrics":[{"dimension":"效率","nature":"V00","text":"集中窗口可减少报价汇总往返，需补单日处理时长、申请量和人工复核工时。"},{"dimension":"质量/风险","nature":"V00","text":"按价格规模期限等规则筛选可增强一致性，需补报价差错率、越权阻断与结果复核记录。"},{"dimension":"经营/管理","nature":"V00","text":"有助统一控制同业存款成本与执行纪律，需补加权资金成本、履约率及比较基线，不能承诺利率下降。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"报价申请、中标与执行警告的案例流程；当前继续运行未核；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"不自动交易、不让模型决定价格或处罚，程序执行也需服从授权制度","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]}]},{"id":"BA06","mark":"渠","name":"渠道与客户服务","desc":"围绕线上线下渠道、客户服务和投诉消保开展分析。","sections":[{"id":"BA06-P01","name":"渠道运营","desc":"分析手机银行、网银和网点的运营表现。","scenes":[{"id":"BA06-P01-S01","title":"网点厅堂服务效能分析与排班优化","definition":"运营管理人员按周期分析网点客流、等候与办理效率，定位影响因素并形成网点辅导、客户分流和排班优化建议。","decision":"AI-L2","maturity":"M2 方案验证","version":"v1.0","flagship":false,"gateway":false,"values":["运营提效","客户与员工体验","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"planned","D04":"partial"},"role":"运营管理人员、厅堂服务项目人员、支行管理人员","trigger":"月度厅堂效能复盘、客流高峰前、网点辅导与排班调整时","task":"监测客流与等候时长→比较同类型网点→从业务、柜员和客户维度归因→识别高峰时点和超时交易→形成辅导与排班建议","dataScope":"网点客流、客户等候时长、业务办理时长、高频交易、超时交易、柜员、客户年龄、营销积分和网点类型。","outputs":"厅堂效能看板、同类网点对比、问题清单、高峰趋势、辅导重点和排班建议。","collaboration":"当前以BI指标和看板分析为主；后续可由Dora或联合Agent生成归因摘要与排班建议。","manualCheck":"确认异常原因、网点辅导重点、客户分流方式和人员排班方案。","before":"网点效能多依赖零散统计和事后反馈，难以横向比较同类网点，也难以定位超时业务、柜员和客流高峰的影响。","after":"BI看板统一展示客流、等候、业务量和超时情况，并按业务、柜员、客户和网点类型下钻，管理人员确认辅导和排班动作。","feedback":"“我能直接看到哪家网点、哪个时点和哪类业务拖慢了效率，辅导和排班都有数据依据。”","metrics":[{"dimension":"效率","nature":"V03 实测参考","text":"作品材料显示2025年6月全行平均等候时长为400秒，较5月缩短60.56秒。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充超时交易识别准确率、数据完整率和异常复核规则。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充辅导完成率、排班调整覆盖率、客户满意度或营销产出观察指标。"}],"quantBasis":"昆山BI大赛时半功倍队作品中的2025年6月厅堂服务效率分析。","scope":"已覆盖2025年6月客流、等候、业务量和部分归因分析；自动趋势预测、排班优化和效果回录尚未形成。","boundary":"客流与等候相关性不等同因果；排班和分流措施需结合服务规范人工审定。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"暂无","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B03","B04"]},{"id":"BA06-P01-S02","title":"收单商户费率敏感度与定价优化","definition":"收单业务管理人员分析不同商户的费率敏感度及交易量变化，平衡商户留存、交易增长和手续费收益并形成定价建议。","decision":"AI-L2","maturity":"M2 方案验证","version":"v1.0","flagship":false,"gateway":false,"values":["经营增长","管理决策","风险合规"],"abilities":{"D01":"done","D02":"partial","D03":"planned","D04":"planned"},"role":"收单业务管理人员、网络金融管理人员、定价审批人员","trigger":"费率政策评估、商户续约、优惠方案制定和区域经营复盘时","task":"汇总商户费率与交易→按行业、规模和区域分组→分析费率与交易量关系→模拟收益和流失影响→形成定价建议","dataScope":"商户行业与规模、手续费费率、历史交易量、费率调整记录、商户留存、区域和手续费收益。","outputs":"费率敏感度分析、行业与商户分组、收益影响比较、差异化费率建议。","collaboration":"当前以BI关联分析和看板为主；后续可叠加敏感度模型、收益模拟和Dora策略解释。","manualCheck":"确认样本口径、定价规则、优惠边界和最终商户费率方案。","before":"商户费率调整多依赖经验或单点比较，难以同时评估行业差异、交易量变化、商户流失和收益影响。","after":"BI看板按行业、规模、区域和费率区间比较交易表现，支持评估不同定价策略的收益与交易量影响，由审批人员确认方案。","feedback":"“我能看到哪些商户真正对费率敏感，也能在优惠、留存和收益之间做有依据的取舍。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充费率分析和方案准备时长的基线与目标。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充样本覆盖、异常交易处理、模型稳定性和定价合规复核口径。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充手续费收益、交易量、商户留存和优惠成本的联合观察指标。"}],"quantBasis":"昆山BI大赛收单费率作品未提供正式试点成效。","scope":"已覆盖费率区间、行业和交易量关联分析；因果识别、收益模拟、策略试验和审批闭环尚待完善。","boundary":"相关性不能直接证明费率调整导致交易量变化；正式定价必须经人工审批。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"暂无","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B03"]},{"id":"BA06-P01-S03","title":"收单商户分层与综合价值经营","definition":"收单运营人员按商户综合价值和生命周期进行分层，识别重点经营对象并形成经人工确认的服务与产品协同清单。","decision":"AI-L3","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["经营增长","管理决策","运营提效"],"abilities":{"D01":"done","D02":"done","D03":"partial","D04":"planned"},"role":"收单业务管理人员、支行负责人、商户客户经理","trigger":"商户日常运营、分层更新、活跃度下降或专项经营活动前","task":"汇聚商户画像→综合评分分层→识别高潜和待提升商户→生成清单→人工确认触达→回录","dataScope":"商户信息、交易规模与频次、收益成本、存贷款与产品、生态关联、活跃度和风险提示。","outputs":"商户画像、分层标签、星级名单、经营机会、机构分布和策略复盘。","collaboration":"模型平台计算评分，Dora解释分层并生成建议；CRM或商户系统承接名单、触达和回录。","manualCheck":"确认分层阈值、重点商户、产品与权益方案、联系授权和触达内容。","before":"支行依赖零散交易报表和个人经验筛选商户，难兼顾交易活跃、收益、综合贡献、生态关系与风险。","after":"系统形成可解释的商户评分、星级与经营分层，按优先级输出活客、留存和综合产品清单并跟踪结果。","feedback":"“我不仅知道哪些商户交易多，还能看懂它为什么值得经营、下一步该提供什么服务。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"以6大类53项特征自动形成分层清单，人工筛选时间下降目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"分层纳入风险维度，标签稳定性、误分率和合规触达率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"覆盖4份参赛作品的商户价值方法，活跃率、留存率和贡献提升目标待确认。"}],"scope":"已有六维指标、TOPSIS/RFM分层及看板方案；自动建议和增量效果验证待建设。","boundary":"价值经营不等于风险处置或费率自动定价，评分不得绕过授权、公平营销和人工判断。","assets":{"方案 PPT":"已有","看板 Demo":"多份材料含原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]},{"id":"BA06-P01-S04","title":"网点资源匹配与布局评估","definition":"渠道管理人员结合网点经营业务量与周边客群POI，评估资源和产出匹配，形成需进一步论证的网络与服务配置建议。","decision":"AI-L2","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"渠道网络与网点资源管理人员（顾问归纳），支行管理者","trigger":"网点周期评价、资源配置和布局调整论证","task":"评估区域客群资源与网点产能产出匹配，选择资源调整方向","dataScope":"存款余额日均、近3个月业务量、网点位置、周边住宅与写字楼POI","outputs":"资源热力图、网点分类、机具人员或规模调整建议","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：渠道负责人核实区域资源、合规与经营约束，决定是否论证调整；数据过时或样本不足时先实地调查。 程序/规则：受控获取POI与坐标、汇总业务量、生成地图及分类比较；不得绕过地图服务许可。 分析模型：可建议资源匹配评分，当前分类规则不能当预测因果模型。 大模型：建议说明分类依据并整理论证要点，不自动宣布网点压降。 Agent：可建议汇集内外部分析证据，投资、撤并和人员调整仍走正式审批。","manualCheck":"渠道负责人核实区域资源、合规与经营约束，决定是否论证调整；数据过时或样本不足时先实地调查。","before":"仅凭网点业绩难判断是区域客群资源不足还是服务资源配置不匹配，业务量和外部环境缺少联动观察。","after":"案例材料结合行内业务量和地图API获取的POI进行网点分类，提出窗口、机具、营销或规模调整建议；未证明建议已审批或实施。","feedback":"“我希望先弄清一家网点是周边资源不够还是配置不合适，再讨论增配、营销或规模调整。”","metrics":[{"dimension":"效率","nature":"V00","text":"集中汇总网点与周期业务量，需补单次评价准备人时和覆盖范围，网点数不等于改善数量。"},{"dimension":"质量/风险","nature":"V00","text":"结合内外部资源开展比较，需补POI完整率、更新日期和分类人工验证率。"},{"dimension":"经营/管理","nature":"V00","text":"支持资源调整论证，需补建议采纳率、投入产出及调整后观察周期，不能承诺收益提升。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"历史区域网点分类及建议；实际布局方案和当前规模未核；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"周边资源与产出是相关分析，不能据此直接关停或缩编网点；日常厅堂排班仍归既有卡","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]},{"id":"BA06-P02","name":"客户服务","desc":"分析服务需求、反馈和服务质量变化。","scenes":[{"id":"BA06-P02-S01","title":"视频银行与网点业务导航及协同转介","definition":"视频银行坐席、网点员工在咨询、转介、线下办理环节，系统识别诉求、判断办理渠道并同步身份、材料与进度，复杂或异常事项由人工接续。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["客户与员工体验","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"partial"},"role":"视频银行坐席、网点员工","trigger":"咨询、转介、线下办理；业务对象或触发范围：视频银行坐席、网点员工与跨渠道客户","task":"识别客户诉求和业务标签→判断办理渠道→生成转介路径→同步身份、材料和进度→闭环反馈","dataScope":"执行渠道分工、业务路由、材料清单、状态同步和流程留痕。","outputs":"编排视频银行、网点系统与客户通知，跟踪转介闭环。","collaboration":"DORA主承接：对话、意图识别和跨系统编排。流程平台：路由与状态。视频/网点系统：业务办理。人工：复杂服务。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"处理复杂诉求和异常转介，确认客户授权与最终办理渠道。","before":"客户在线上线下渠道间转介时需重复描述诉求和提交材料，进度容易中断。","after":"系统识别诉求、判断办理渠道并同步身份、材料与进度，复杂或异常事项由人工接续。","feedback":"“我转到网点或视频坐席后不用重新讲一遍，办理进度也能一直查到。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"跨渠道重复录入与材料准备时间减少40%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"转介信息完整率达到95%以上，客户授权校验覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"转介任务按期闭环率达到90%以上，客户折返或退办率下降20%以上。"}],"quantBasis":"Excel“独立场景库”OC-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"明确渠道职责、数据共享权限和客户同意；转介状态必须可追踪。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]},{"id":"BA06-P03","name":"投诉与消保","desc":"归集投诉消保问题并支持分析、报告和跟踪。","scenes":[{"id":"BA06-P03-S01","title":"投诉工单智能分类、归因与改进建议","definition":"投诉处理与消费者保护人员在投诉受理、归因、整改环节，工单自动分类、检索相似案例并生成回复和根因初稿，人工审核后进入整改与复盘闭环。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["运营提效","风险合规"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"投诉处理与消费者保护人员","trigger":"投诉受理、归因、整改；业务对象或触发范围：逾期催收、利息、违约金等零售投诉工单","task":"解析工单与来电文本→自动分类和相似工单检索→归因业务流程问题→生成反馈与整改建议→跟踪整改效果","dataScope":"接入工单、执行路由和SLA规则、检索相似工单并记录整改状态。","outputs":"编排分类、检索、回复审核、整改任务和效果复盘。","collaboration":"DORA主承接：文本理解、回复建议和整改Agent。投诉系统：工单、时效和留痕。模型服务：分类聚类。人工：正式回复与整改。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"复核投诉分类与回复，确认根因和整改措施，跟踪客户反馈。","before":"投诉文本靠人工阅读分类和归因，标准不一，正式回复与整改跟踪相互割裂。","after":"工单自动分类、检索相似案例并生成回复和根因初稿，人工审核后进入整改与复盘闭环。","feedback":"“我能快速看到投诉事实、相似案例和建议回复，同时清楚哪些问题必须人工判断。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"投诉分类与初稿自动处理覆盖率达到80%以上，平均处理时长减少30%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"分类准确率达到90%以上，所有正式回复保持100%人工审核。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"重复投诉识别率达到90%以上，整改事项按期闭环率达到90%以上。"}],"quantBasis":"Excel“独立场景库”OC-03。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"客户沟通文本涉及敏感信息；生成回复需人工审核；不得以自动化掩盖实质问题。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]}]},{"id":"BA07","mark":"险","name":"授信与准入","desc":"覆盖客户准入、授信审查、审批管理和信贷投放，支持单笔业务判断与授信流程管理。","sections":[{"id":"BA07-P01","name":"准入、审查与审批","desc":"支持客户准入、授信审查、放款审核和审批效能管理。","scenes":[{"id":"BA07-P01-S01","title":"炼化行业绿色风险分级与准入","definition":"信贷审查人员、绿色金融管理人员在贷前评审环节，环评、排污和碳排数据按统一规则形成分级与准入提示，并展示关键因子供人工审定。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"信贷审查人员、绿色金融管理人员","trigger":"贷前评审；业务对象或触发范围：炼化行业授信客户","task":"采集环评、排污、碳排等信息→指标加权评分→形成绿/蓝/黄/黑分级→匹配白名单或否决规则→人工审定","dataScope":"接入环评、排污和碳排数据，按规则计算分级并执行白名单或否决条件。","outputs":"编排数据采集、评分、解释和人工复核。","collaboration":"DORA辅助承接：政策问答、解释和流程编排。规则/模型服务：评分。信贷系统：准入审批。人工：权重和最终准入。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确定指标权重和准入政策；复核边界客户并作出准入决定。","before":"炼化行业绿色风险主要依靠信贷人员经验判断，指标、权重和准入口径缺少统一标准。","after":"环评、排污和碳排数据按统一规则形成分级与准入提示，并展示关键因子供人工审定。","feedback":"“我面对边界客户时能看到统一评分和政策依据，不再只凭个人经验做准入判断。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"单户绿色风险评价准备时间减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"准入必核指标覆盖率达到95%以上，一票否决项人工确认率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"炼化客户统一分级覆盖率达到90%以上，跨机构口径差异减少30%以上。"}],"quantBasis":"Excel“独立场景库”CP-07。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"需验证指标权重和一票否决规则；避免把绿色评级等同于完整信用评级。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA07-P01-S02","title":"授信审批效率诊断与超时预警","definition":"授信审批管理人员在授信审批全流程环节，全流程时间戳实时汇集，预测剩余时长并提前预警，管理人员据此定位瓶颈和安排资源。","decision":"AI-L2","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"授信审批管理人员","trigger":"授信审批全流程；业务对象或触发范围：总行、审批团队、机构及审批人员的在途业务","task":"汇集节点时间戳→看板监测业务量和时效→预测剩余审批时长→超时预警→分析影响因素→形成月度报告","dataScope":"采集节点时间戳，计算各环节耗时，展示看板并按阈值预警。","outputs":"定时刷新数据，调用预测服务，触发预警和整改任务。","collaboration":"DORA主承接：自然语言分析、报告和预警编排。BI/流程平台：时效看板。模型服务：预测。审批系统：节点数据。人工：整改决策。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"设定时效目标与例外规则；确认积压原因并安排资源或流程整改。","before":"审批时效依靠事后报表统计，积压和超时通常在问题发生后才被发现。","after":"全流程时间戳实时汇集，预测剩余时长并提前预警，管理人员据此定位瓶颈和安排资源。","feedback":"“我不必等月报才发现积压，能提前看到哪些业务可能超时并及时调整资源。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"审批平均周转时间缩短20%以上，月度统计工作量减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"超时风险预警召回率达到80%以上，误报率控制在20%以内。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"高风险积压事项24小时内处置启动率达到90%以上；原课题含模拟数据，以上指标需生产验证。"}],"quantBasis":"Excel“独立场景库”CR-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。","boundary":"需接入真实流程时间戳并校准标签；原课题部分数据为模拟数据，量化效果需生产验证。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03"]},{"id":"BA07-P01-S03","title":"对公财务报表量化初筛与异常预警","definition":"对公授信审查人员在授信申报初审环节，财报结构、指标和附注自动解析，异常按规则标记并生成初筛结论，人员聚焦专业判断。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["运营提效","风险合规"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"对公授信审查人员","trigger":"授信申报初审；业务对象或触发范围：申报授信的对公企业财务报表","task":"解析财报→自动计算偿债、盈利、营运指标→比对风控阈值→标记异常→输出初筛结论→审批人员复核","dataScope":"解析表内结构，计算财务指标并按阈值规则标记异常。","outputs":"编排财报解析、公式计算、规则校验与人工复核。","collaboration":"DORA主承接：非结构化解释、初筛报告和工具编排。财务计算服务：指标与阈值。信贷系统：审批流程。人工：专业判断。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"核验财报口径和异常事项；形成专业财务判断。","before":"审查人员逐项录入财报、计算指标并对照阈值，重复劳动多且容易漏判。","after":"财报结构、指标和附注自动解析，异常按规则标记并生成初筛结论，人员聚焦专业判断。","feedback":"“我拿到财报后很快就能看到关键指标和异常出处，复核比重新计算更省时间。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"单户财报初筛由约2小时压缩至1小时以内。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"核心财务指标自动计算覆盖率达到95%以上，漏判与返工率下降20%以上。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"统一初筛模板在90%以上对公申报中使用，异常项人工确认率保持100%。"}],"quantBasis":"Excel“独立场景库”CR-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"维护公式与阈值版本；识别报表口径和异常数据；初筛不替代专业财务分析。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA07-P01-S04","title":"放款前置条件与交易材料智能审查","definition":"放款审查人员在授信批复后、放款前环节，OCR、验真和确定性规则先完成跨文档一致性校验，大模型解释复杂条款并输出疑点清单。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["运营提效","风险合规"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"放款审查人员","trigger":"授信批复后、放款前；业务对象或触发范围：对公用信、出账及放款申请材料","task":"OCR和要素抽取→合同、发票、用款申请、批复多方一致性校验→刚性规则核验→风险疑点清单和审查报告→人工复核","dataScope":"执行合同、发票、用款申请、批复的字段校验和跨文档一致性规则。","outputs":"调用OCR、验真、规则和报告服务，汇总风险分级并进入人工复核。","collaboration":"DORA主承接：语义审查、报告和工具编排。外部服务：OCR、规则、发票验真。信贷系统：影像与审批。人工：放款决定。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"复核阻塞项与疑点；完成放款审查并承担审批责任。","before":"审查人员在合同、发票、批复和用款材料之间逐项勾稽，耗时长且错漏难追溯。","after":"OCR、验真和确定性规则先完成跨文档一致性校验，大模型解释复杂条款并输出疑点清单。","feedback":"“我可以直接复核被标出的差异和原文，不必从头翻完每一份材料。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"合同审查由2—5小时压缩至约30分钟，整体审查由2小时—2天缩短至30分钟—半天。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"风险预警效率提升90%以上，刚性前置条件校验覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"材料差异一次定位率达到90%以上，补件往返次数下降30%以上。"}],"quantBasis":"Excel“独立场景库”CR-05。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"刚性条件由规则判定；语义结论需引用原文；高风险和阻塞项必须人工确认。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA07-P01-S05","title":"多源流水驱动的零售客户真实收入评估","definition":"零售信贷审查人员在个贷调查、审批与贷后环节，授权流水自动清洗、分类和估算稳定收入，异常交易与自循环证据被集中展示供人工核验。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"零售信贷审查人员","trigger":"个贷调查、审批与贷后；业务对象或触发范围：收入不稳定或需核验还款能力的个人贷款申请人","task":"获取授权流水→摘要分类和异常清洗→估算稳定月收入与波动区间→行业基准交叉验证→识别自循环→输出评估报告","dataScope":"采集授权流水，执行清洗、去重、科目归集和基础收支计算。","outputs":"编排流水处理、模型分析、报告生成和人工复核。","collaboration":"DORA主承接：解释、报告和流程编排。安全数据/模型服务：敏感流水处理。信贷系统：授信流程。人工：真实性和授信判断。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认客户授权和流水真实性；核验收入结论并形成授信判断。","before":"调查人员逐笔查看多渠道流水并手工归类加总，非固定收入难判断，客户补料多。","after":"授权流水自动清洗、分类和估算稳定收入，异常交易与自循环证据被集中展示供人工核验。","feedback":"“我几分钟就能看懂客户收入结构和异常流水，调查结论也更容易说明依据。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"单户流水分析由约45分钟压缩至5分钟以内，效率提升85%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"主要收入类别识别准确率达到90%以上，自循环高风险线索人工复核率保持100%。"},{"dimension":"经营/管理","nature":"V01 申报目标","text":"审批等待由2—3天缩短至半天，建议试点将重复补料次数降低30%以上。"}],"quantBasis":"Excel“独立场景库”CR-09。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"确保客户授权和最小必要使用；识别现金与非工资收入边界；模型结论由调查和审批人员复核。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]},{"id":"BA07-P02","name":"授信政策与投放管理","desc":"跟踪授信政策、重点指标、投放进度与信贷结构，支持机构整改和投放管理。","scenes":[{"id":"BA07-P02-S02","title":"授信重点指标与政策契合度监测","definition":"授信管理人员、分支机构负责人在授信管理、经营监测环节，明细数据按统一政策口径T+1计算，掉队或超限自动预警并形成机构整改待办。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"授信管理人员、分支机构负责人","trigger":"授信管理、经营监测；业务对象或触发范围：分支机构授信业务与重点监管、经营指标","task":"对接信贷和网贷明细→按政策规则计算契合度与重点指标→T+1看板→掉队或超限预警→指导机构营销与调整","dataScope":"对接明细数据，计算契合度和重点指标，执行T+1刷新与阈值预警。","outputs":"编排数据刷新、规则计算、预警和督办任务。","collaboration":"DORA辅助承接：政策问答、摘要和督办编排。数据/BI平台：指标计算和看板。信贷系统：明细来源。人工：口径与整改。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"维护政策口径；确认定性指标，督导掉队或超限机构整改。","before":"重点指标由各机构手工跨系统统计，通常到月度汇总后才发现偏离。","after":"明细数据按统一政策口径T+1计算，掉队或超限自动预警并形成机构整改待办。","feedback":"“我每天都能看到指标偏离和原因，不用等到月底再追着机构补数据和整改。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"重点指标监测达到T+1，问题响应由次月发现前移到当日或次日。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"核心指标口径一致率达到100%，定性指标人工复核率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"手工统计工作量减少70%以上，预警事项按期整改闭环率达到90%以上。"}],"quantBasis":"Excel“独立场景库”CR-03。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"指标口径和政策版本需统一；绿色、科技等定性判定需保留人工复核。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA07-P02-S03","title":"授信投放、已批未投与信贷结构优化","definition":"信贷管理人员、客户经理在批复、投放、定价、组合监测环节，系统自动解析台账、识别高潜已批未投客户和结构偏离，并向条线派发跟进与预警任务。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"信贷管理人员、客户经理","trigger":"批复、投放、定价、组合监测；业务对象或触发范围：已批授信、已投放贷款及机构/条线/行业组合","task":"自动解析批复与投放台账→识别已批未投客户→分析机构、条线、行业与定价结构→输出客户清单和结构优化建议","dataScope":"解析批复与投放台账，计算集中度、投放率和定价偏离。","outputs":"定时运行台账、模型与报告，向条线派发客户和预警任务。","collaboration":"DORA主承接：问数、解释、报告和任务编排。数据/模型服务：组合计算和客户评分。CRM/信贷系统：跟进与投放。人工：决策。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"决定客户跟进、利率定价和组合结构调整。","before":"已批未投、定价和组合结构数据分散在批复与投放台账中，汇总慢且客户跟进滞后。","after":"系统自动解析台账、识别高潜已批未投客户和结构偏离，并向条线派发跟进与预警任务。","feedback":"“我能直接拿到该优先跟进的客户和结构问题，不再花几天汇总台账。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"数据汇总工作量减少80%以上，人工操作量减少70%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"高潜已批未投客户识别能力提升60%以上，并对定价和集中度规则保留100%校验。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"高潜客户任务7日内跟进率达到90%以上，已批未投转化率提升10%以上。"}],"quantBasis":"Excel“独立场景库”CR-04。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"统一批复、合同、放款口径；防止名单重复营销；结构建议不得绕过风险限额。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B04"]}]}]},{"id":"BA08","mark":"合","name":"合规、反洗钱、审计与法务","desc":"服务检查、调查、审计、整改和制度法务工作。","sections":[{"id":"BA08-P01","name":"合规与反洗钱检查","desc":"归集检查数据并识别待人工核验的问题线索。","scenes":[{"id":"BA08-P01-S01","title":"对公反洗钱预警智能复核与风险评级","definition":"反洗钱调查人员在监测预警核查环节，客户、交易、规则和模型结果被汇成可解释案件包，自动提示核查要点，人工完成可疑认定。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"反洗钱调查人员","trigger":"监测预警核查；业务对象或触发范围：触发可疑交易预警的对公账户","task":"整合客户经营、开户与交易特征→解析预警上下文→构建洗钱风险标签和评级→提示核查要点与材料→人工认定","dataScope":"计算交易规则、风险标签、核查清单和材料要求。","outputs":"汇聚客户、交易、规则和模型结果，形成待复核案件包。","collaboration":"DORA辅助承接：案件摘要、解释和资料编排。反洗钱平台：规则、模型、案件和上报。人工：可疑认定与管控。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"完成客户尽调与可疑交易人工认定，决定上报和管控措施。","before":"反洗钱人员逐条查看流水和客户资料并解释预警，单案耗时长且误报排除依赖经验。","after":"客户、交易、规则和模型结果被汇成可解释案件包，自动提示核查要点，人工完成可疑认定。","feedback":"“我能从一个案件包看到预警原因和所需证据，但可疑认定仍由我最终把关。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标（含材料基线）","text":"人工复核约1小时/案，试点目标压缩至30分钟以内。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"高风险线索召回率达到90%以上，可疑交易人工认定率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"案件材料完整率达到95%以上，误预警人工排查工作量减少30%以上。"}],"quantBasis":"Excel“独立场景库”AC-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"符合反洗钱模型验证和监管要求；保留人工可疑交易认定；所有结论可解释、可审计。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA08-P01-S02","title":"不法贷款中介风险监测与线索核查","definition":"风险与审计人员贯通贷前、贷中、贷后和审计数据，发现疑似不法中介线索并经人工穿透核查。","decision":"AI-L3","maturity":"M2 方案验证 · 试用范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["风险合规","运营提效","管理决策"],"abilities":{"D01":"done","D02":"done","D03":"partial","D04":"planned"},"role":"分管风险行领导、风险管理部、审计部、支行客户经理","trigger":"周期监测、专项检查、风险信号命中、审计发现或处置超期时","task":"汇聚三道防线数据→诊断异常→下钻客户合同和流水→生成线索佐证→人工核查→复盘规则","dataScope":"信贷、核心、反欺诈模型、审计疑点、员工信息、调查记录、授信条件和关联账户。","outputs":"风险总览、机构分布、疑点客户与流水、关联线索、核查清单和结论记录。","collaboration":"规则与图谱平台负责筛查，Dora聚合线索并生成核查材料；风险、审计和支行人员完成取证与定性。","manualCheck":"确认关联真实性、证据充分性、问题定性、责任认定和处置。","before":"各部门分别维护推进表和疑点清单，关联客户、员工、合同和资金流向需要人工拼接。","after":"系统以监控—诊断—溯源框架统一5类指标，支持机构排名和疑点下钻，人工核查后形成结论。","feedback":"“我可以从全行风险态势直接下钻到具体客户和疑点流水，但系统不会替我下违规结论。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"整合5个一级、15个二级指标，材料称可数分钟定位问题，需真实试点验证。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"覆盖贷前、贷中、贷后和审计疑点，命中率、误报率和核查率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"服务决策、管理、监督和执行4类角色，专项检查周期和整改率目标待确认。"}],"scope":"已形成统一监控原型；部分要素仍需人工格式化，正式试用与工单闭环待核实。","boundary":"疑似关联不等于违规、欺诈或员工责任，不得仅凭模型直接采取纪律或授信措施。","assets":{"方案文档":"已有","看板 Demo":"已有原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]}]},{"id":"BA08-P02","name":"审计与整改","desc":"管理审计问题、责任和整改过程。","scenes":[{"id":"BA08-P02-S01","title":"隐性关联风险图谱问答与穿透核查","definition":"审计、客户经理与风险人员在疑点挖掘、穿透核查、线索研判环节，自然语言问题被转换为受控图查询，系统展示关系路径、来源、时点和风险线索供人工核查。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"审计、客户经理与风险人员","trigger":"疑点挖掘、穿透核查、线索研判；业务对象或触发范围：审计人员、客户经理及风险人员查询的企业关系与资金链路","task":"构建担保、股权和资金子图→自然语言解析查询意图→检索和推理关联链路→可视化证据与风险线索→人工核查","dataScope":"进行实体对齐、关系入图、权限控制和确定性图查询。","outputs":"调用图谱查询、路径分析和报告工具，保留完整查询证据。","collaboration":"DORA主承接：自然语言入口、解释和Agent编排。图数据库/图计算服务：关系和路径。审计系统：底稿与结论。人工：核查。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"设定核查范围，验证关联链路和证据，形成审计结论。","before":"审计人员在担保、股权和资金数据中反复查找关系，复杂链路难以快速还原和留证。","after":"自然语言问题被转换为受控图查询，系统展示关系路径、来源、时点和风险线索供人工核查。","feedback":"“我可以直接追到关联链路和原始证据，不必在多个系统里反复拼接关系。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"复杂关联查询与证据整理时间减少70%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"展示链路的数据来源和时点覆盖率达到100%，推断关系人工核验率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"重点疑点发现量提升20%以上，审计线索按期核查闭环率达到90%以上。"}],"quantBasis":"Excel“独立场景库”AC-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"区分已确认关系与推断链路；结果需展示数据来源、时点和路径；不得将关联等同违规。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA08-P02-S02","title":"巡审联动审前风险画像","definition":"审计与纪律监督人员在巡审联动前形成支行全面风险画像，定位重点业务、重点人员和问题并确定检查重点。","decision":"AI-L2","maturity":"M2 方案验证","version":"v1.0","flagship":false,"gateway":true,"values":["风险合规","运营提效","管理决策"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"planned"},"role":"审计稽核人员、纪律监督人员、检查组负责人和管理人员","trigger":"支行巡审联动立项、审前分析、检查方案制定和领导决策时","task":"汇集贷款、存款、党建、合规、审计和纪检数据→形成支行风险画像→定位重点业务、人员和问题→生成检查重点→人工确认方案","dataScope":"贷款、存款、党建、合规管理、历史审计、纪检监督、机构与人员信息。","outputs":"支行全面风险画像、重点业务与人员清单、问题线索、审前分析材料和检查重点。","collaboration":"当前以BI多源画像和看板为主；后续可由Dora或联合Agent生成疑点摘要与检查清单。","manualCheck":"确认数据口径、问题线索、检查范围、审计定性和整改要求。","before":"审前分析需要人工从业务、审计、纪检和合规资料中筛查线索，数据分散、重点不清，检查组准备耗时。","after":"BI看板整合多源数据并形成支行风险画像，按业务、人员和问题维度定位异常，检查组据此确认审计范围和重点。","feedback":"“我能在进场前看清一家支行最值得关注的业务、人员和问题，把检查力量放到真正的风险点上。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充审前资料汇集与筛查人时的基线和目标。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充重点线索命中率、证据覆盖率和人工核验要求。"},{"dimension":"经营/管理","nature":"V03 实测参考","text":"作品材料用于2025年度巡审联动，涉及8家支行；仅表示材料适用范围。"}],"quantBasis":"昆山BI大赛数智铁稽队作品所述2025年度巡审联动范围。","scope":"已覆盖支行贷款、存款、党建和合规等风险画像；线索证据链、检查任务和整改闭环尚待补充。","boundary":"风险画像只用于审前筛查和范围确定，异常指标不等于违规事实；审计定性由检查人员确认。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"暂无","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B03"]}]}]},{"id":"BA09","mark":"运","name":"运营管理","desc":"围绕业务处理效率、作业产能、差错质量开展数据分析。","sections":[{"id":"BA09-P01","name":"业务受理与集中作业","desc":"跟踪业务量、处理时效、产能和积压情况。","scenes":[{"id":"BA09-P01-S01","title":"业务材料要素抽取与模板批量填充","definition":"客户经理、运营作业人员在用信出账、材料制备环节，权威字段一次抽取后按可维护模板批量填充，低置信度和关键字段集中提示人工核对。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"客户经理、运营作业人员","trigger":"用信出账、材料制备；业务对象或触发范围：需要在多份业务材料重复填写客户和业务信息的客户经理","task":"导入客户材料或读取系统字段→抽取一次要素→匹配可维护模板→批量填充→人工校验→输出材料","dataScope":"读取权威字段、映射模板、批量填充、导出和版本控制。","outputs":"调用OCR、字段映射和模板服务，提示人工校验项。","collaboration":"DORA辅助承接：语义映射、校验提示和工具编排。文档服务：OCR和模板填充。业务系统：权威字段。人工：模板与最终校验。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"维护模板与字段映射，核对生成材料并正式提交。","before":"同一客户和业务信息被反复填写到多份材料中，人工复制粘贴耗时且容易错填。","after":"权威字段一次抽取后按可维护模板批量填充，低置信度和关键字段集中提示人工核对。","feedback":"“我只需核对关键字段就能一次生成多份材料，不再重复复制相同信息。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"单次材料准备由30—60分钟压缩至约5分钟。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"关键字段填充准确率达到98%以上，低置信度字段人工复核率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"重复录入工作量减少80%以上，因错填导致的退回率下降30%以上。"}],"quantBasis":"Excel“独立场景库”OC-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"优先通过系统接口获取权威字段；本地文件需加密与自动清理；输出必须人工核对。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]}]},{"id":"BA10","mark":"财","name":"财务、资产负债与资本管理","desc":"围绕预算、盈利和资产负债管理提供统一口径分析。","sections":[{"id":"BA10-P02","name":"盈利与资产负债管理","desc":"分析盈利结构、定价、流动性和资产负债变化。","scenes":[{"id":"BA10-P02-S01","title":"贷款定价执行与收息率归因分析","definition":"财务与定价管理人员从趋势、结构、策略和机构执行四层定位收息率变化原因，形成经授权确认的优化建议。","decision":"AI-L2","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["管理决策","经营增长","风险合规"],"abilities":{"D01":"done","D02":"done","D03":"partial","D04":"partial"},"role":"财务与资产负债管理人员、信贷定价管理人员、机构负责人、客户经理","trigger":"月季收益分析、利率政策调整、收息率异常、机构对标和策略复盘时","task":"汇聚业务财务风控数据→分析趋势→拆解贡献→检查风险收益匹配与执行偏差→人工决策","dataScope":"贷款规模、利息收入、收息率、净息差、产品、客群、评级、违约概率、机构和定价记录。","outputs":"收息率趋势、产品与客群贡献、风险收益矩阵、机构画像、重点客户和复盘建议。","collaboration":"Dora解释收息率归因并生成建议；定价、FTP、信贷和财务系统提供事实与规则；价格审批由人工完成。","manualCheck":"确认数据口径、归因结论、异常原因、定价政策、授权边界和管理动作。","before":"收息率下降后依赖人工拼接业务、财务和风控数据，难回答“什么在降、为什么降、哪里最严重”。","after":"系统以四层分析链拆解收息率，定位风险收益错配和异常机构、客户经理与客户，生成可追溯建议。","feedback":"“我不只看到收息率下降，还能沿着结构和执行链找到具体产品、机构和客户。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"统一总体、趋势结构、定价策略和机构执行4层分析，取数归因时长目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"联动评级、违约概率和执行利率识别高风险低定价，复核率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"分析近10年趋势并提供两个Top10清单，净息差与收益改善目标待确认。"}],"scope":"已有趋势、结构、定价和机构执行分析；动态监控和决策闭环仍需验证。","boundary":"不自动决定贷款价格或调整利率，差异化定价和授权审批必须由人工确认。","assets":{"方案文档":"已有","看板 Demo":"材料含设计","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]},{"id":"BA10-P02-S02","title":"存款结构、期限与付息成本分析","definition":"资产负债管理人员穿透存款规模、期限、到期和机构付息率，识别结构性成本问题并形成经人工确认的调整建议。","decision":"AI-L2","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["管理决策","经营增长","风险合规"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"planned"},"role":"资产负债管理人员、财务人员、存款业务管理人员、支行负责人","trigger":"月季资产负债分析、存款到期窗口、付息率异常和利率政策调整时","task":"汇聚存款余额和成本→分析活定期结构→查看期限与到期→对标付息率→形成建议→人工决策","dataScope":"存款余额、客户数、活定期、对公对私、期限、到期日、付息率、机构和资金变动。","outputs":"存款总览、结构趋势、三年到期分布、机构付息率排名、成本异常和结构建议。","collaboration":"Dora解释结构和成本变化并生成报告；核心与资产负债系统提供事实与政策；定价和客户策略由授权人员决定。","manualCheck":"确认口径、成本归因、利率政策、机构策略、客户动作和公平性审查。","before":"各机构分别统计余额和增幅，活定期、存期、未来到期与付息成本难以联动分析。","after":"系统统一展示规模、客户、四类存款结构、三年到期分布和机构付息率排名，形成优化建议。","feedback":"“我能同时看到存款有没有增长、什么时候到期和增长付出了多少资金成本。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"集中分析单户50万元以上客户及未来3年到期分布，报表准备时长目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"统一4类存款结构口径，到期预警覆盖率和口径一致率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"联动余额增幅与付息率排名，低成本资金占比和付息率改善目标待确认。"}],"scope":"已有规模、客户、期限、到期和机构付息率分析；预警和策略模拟仍需验证。","boundary":"不自动执行差异化存款定价，结构优化需遵守利率政策、流动性约束和消费者公平。","assets":{"方案 PPT":"已有","看板 Demo":"已有PDF/BI作品","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]},{"id":"BA10-P02-S03","title":"网点现金需求汇总与调配","definition":"分行计财人员汇总支行网点的次日现金使用申请，核查需求与库存后形成经授权确认的调配安排。","decision":"AI-L2","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["管理决策","运营提效","风险合规"],"abilities":{"D01":"done","D02":"planned","D03":"partial","D04":"partial"},"role":"分行计划财务部、支行/网点现金需求申报人员","trigger":"每日次日现金计划编制和申请变化","task":"掌握次日现金需求并合理调配库存","dataScope":"网点头寸使用申请、次日需求汇总；库存与调运约束为需补数据","outputs":"次日申请汇总、现金缺口与人工调配依据","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：确认申请真实性、库存和调运安全约束，审定调配；需求异常先联系网点复核，资金不能自动转移。 程序/规则：收集申请、按机构日期汇总和保留变更；库存匹配与阈值检查需补接口后验证。 分析模型：可建议预测现金需求，案例材料无预测模型。 大模型：建议解释缺口和整理调配理由，计算必须引用系统结果。 Agent：可建议汇总待审安排和提醒，不自动调拨、支付或安排押运。","manualCheck":"确认申请真实性、库存和调运安全约束，审定调配；需求异常先联系网点复核，资金不能自动转移。","before":"分行计财每天需要掌握各支行头寸使用情况，汇总和库存调配依赖对各网点需求的及时收集。","after":"案例材料由支行和网点发起申请，分行计财查询次日汇总并据此调配现金；未证明自动预测、自动下发或押运排程。","feedback":"“我希望一次看清明天各网点要多少现金，再结合库存和安全约束安排调配。”","metrics":[{"dimension":"效率","nature":"V00","text":"将每日次日申请集中汇总，需补每日准备人时、补报次数和处理截止时点。"},{"dimension":"质量/风险","nature":"V00","text":"可减少漏报与版本混用，需补申请完整率、核对差错率及调运安全复核记录。"},{"dimension":"经营/管理","nature":"V00","text":"有助匹配现金库存与网点需求，需补现金缺口、闲置库存和应急调运成本，不能承诺库存下降幅度。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"网点申请及分行次日汇总；自动调配与预测均未证实；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"本例是现金库存需求，不扩写为全行流动性交易策略，实际运营归口需核","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]},{"id":"BA10-P02-S04","title":"EVA价值驱动与波动诊断","definition":"计财分析人员在EVA波动或预算检视时沿价值树分解业务贡献、规模价格与FTP因素，定位机构产品和客群层面的价值变化。","decision":"AI-L2","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"done","D02":"done","D03":"partial","D04":"planned"},"role":"总行计划财务分析人员","trigger":"月季经营分析、EVA异常或预算差距诊断","task":"定位EVA目标差距及价值驱动变化，形成财务经营解释","dataScope":"经审定EVA口径、预算、存贷款与中收、FTP、规模价格、机构产品客群及资本成本","outputs":"价值树、EVA差距、因素分解与多维下钻分析","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：批准财务口径和因素解释，核实资本成本等边界，决定预算或经营调整；对不上账时暂停结论并对账。 程序/规则：按已批准公式计算EVA与因素贡献、预算差距和下钻；文中近似利润解释不能直接成为正式核算公式。 分析模型：当前是确定性财务分解，非自动因果识别；若有情景模型须验证假设。 大模型：建议解释已计算的贡献与差距，区分会计分解和经营因果。 Agent：可建议汇总分析材料交给相关场景会议流程；不跨权限取数或自动调整定价预算。","manualCheck":"批准财务口径和因素解释，核实资本成本等边界，决定预算或经营调整；对不上账时暂停结论并对账。","before":"财务经营分析取数和口径不统一，汇报可能停在结论层，规模、价格及价值创造因素难在同一分析链中核对。","after":"案例材料一期围绕总行计财构建经营总览、EVA价值树与波动诊断，按业务及规模价格FTP下钻；实际因子结果、生产口径和持续运行仍待核实。","feedback":"“我希望沿同一价值树看清EVA差距来自哪类业务和哪些价格规模因素，再核实经营原因。”","metrics":[{"dimension":"效率","nature":"V00","text":"统一存款、贷款、中间业务3类EVA分析入口，需补月季取数与因素分析人时，3类只是设计范围。"},{"dimension":"质量/风险","nature":"V00","text":"沿价值树核对规模价格FTP贡献，需补因素分解对账率、公式版本和资本成本口径，不能声称归因准确率100%。"},{"dimension":"经营/管理","nature":"V00","text":"支持EVA目标差距与资源讨论，需补建议采纳和经对照的EVA改善，当前未提供收益提升数字。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"一期财务EVA方案与分析设计；全行督办与跨条线推广为后续规划；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"会计分解不等于因果归因，不用大模型生成计算事实，不自动调定价或预算","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]},{"id":"BA10-P03","name":"资本与监管报送","desc":"支持资本管理和监管报送分析。","scenes":[{"id":"BA10-P03-S01","title":"EAST规则筛查与数据质量核验","definition":"监管数据质量人员维护筛查规则并运行数据检核，跟踪问题趋势与明细，形成需业务或数据部门复核的问题清单。","decision":"AI-L1","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"partial"},"role":"监管报送/数据质量管理责任人员（顾问归纳，部门待核）","trigger":"规则更新、监管数据检核或周期质量检查","task":"按批准规则筛查数据问题并复核明细","dataScope":"EAST相关数据、筛查模型文件、规则描述及问题明细","outputs":"筛查结果、质量问题明细、趋势及待复核项","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：确认监管规则与筛查含义，核查问题并决定修正，未经授权不得改生产或报送数据。 程序/规则：维护规则元信息、执行已批准文件的检核并生成明细；规则文件执行须在受控平台内。 分析模型：案例材料模型可能是规则脚本，不认定机器学习。 大模型：建议解释已确认的规则与问题描述，不替代监管规则解释权。 Agent：可建议整理复核包与责任清单；整改、提交和自动清洗生效需另验审批控制。","manualCheck":"确认监管规则与筛查含义，核查问题并决定修正，未经授权不得改生产或报送数据。","before":"案例材料未给完整旧作业流程；顾问判断多项规则和数据问题需要统一维护及复核，不编造手工耗时。","after":"案例材料通过上传模型文件进行筛查清洗，查看乱象趋势与不合规数据明细；模型技术类别、整改回录和正式报送接口未明。","feedback":"“我希望每条质量问题能对应到筛查规则和明细，先核清数据问题再决定如何整改。”","metrics":[{"dimension":"效率","nature":"V00","text":"集中规则运行和明细管理可减少逐项排查，需补检核批次耗时与规则维护人时。"},{"dimension":"质量/风险","nature":"V00","text":"保留规则及问题趋势有助复核，需补误报率、漏检率和问题确认样本，不能把筛查命中当违规事实。"},{"dimension":"经营/管理","nature":"V00","text":"可支持质量整改优先级，需补问题整改周期和复发率，尚无可验证改善数字。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"规则文件管理、筛查、问题趋势与明细；整改和报送闭环待补；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"不把模型等同大模型，不将不合规数据自动定性为违规业务，不等同H01正式统计报送","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]}]},{"id":"BA11","mark":"综","name":"综合管理与员工赋能","desc":"服务银行内部管理、员工问数和任务协同。","sections":[{"id":"BA11-P03","name":"采购、培训与行政","desc":"服务采购、培训、知识和行政管理。","scenes":[{"id":"BA11-P03-S01","title":"新员工业务操作与产品知识智能陪练","definition":"新入职柜员和客户经理、带教师傅在日常学习、业务办理、带教复盘环节，知识助手按最新制度提供有出处的操作问答与情景陪练，并根据学习记录识别薄弱项。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["客户与员工体验","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"新入职柜员和客户经理、带教师傅","trigger":"日常学习、业务办理、带教复盘；业务对象或触发范围：新入职柜员和客户经理","task":"按场景提问→检索操作规程和产品知识→给出步骤、要件、话术和常见问答→记录学习行为→识别薄弱点→针对性辅导","dataScope":"管理文档版本、权限、学习记录和知识失效日期。","outputs":"编排问答、练习、学习记录、薄弱项分析和辅导提醒。","collaboration":"DORA主承接：知识问答、陪练和学习Agent。知识管理服务：版本与权限。培训系统：学习记录。人工：知识审核与辅导。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"知识责任人维护制度与产品口径；师傅处理复杂问题并开展辅导。","before":"新人依赖师傅回答系统操作和产品问题，知识更新快，服务话术与产品口径容易不一致。","after":"知识助手按最新制度提供有出处的操作问答与情景陪练，并根据学习记录识别薄弱项。","feedback":"“我遇到常见问题可以先查到有制度依据的答案，也知道哪些复杂事项必须请教师傅。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"师傅重复答疑量减少40%以上，新人查找常见问题时间减少60%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"回答引用制度与生效日期覆盖率达到100%，敏感业务人工确认率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"新人达到独立作业标准的时间缩短20%以上，必修场景训练完成率达到95%以上。"}],"quantBasis":"Excel“独立场景库”HR-01。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"知识库需有版本和责任人；敏感交易不得只凭助手办理；答案必须提示制度依据和生效日期。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]}]},{"id":"BA12","mark":"数","name":"科技、数据与安全运营","desc":"服务科技运营、数据资产治理和安全管理。","sections":[{"id":"BA12-P01","name":"需求、研发与运维","desc":"跟踪科技需求、研发交付和运维运行情况。","scenes":[{"id":"BA12-P01-S01","title":"银行系统上线后全链路评价与改进闭环","definition":"科技管理与系统运营人员在系统上线后持续评价环节，监控、业务、ITSM和客服数据按统一口径形成全链路评价，问题自动分派并组织复评。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"科技管理与系统运营人员","trigger":"系统上线后持续评价；业务对象或触发范围：核心、网银、手机银行、卡系统等已上线系统","task":"采集监控、业务、ITSM和客服数据→计算稳定性、性能、使用、运维等指标→异常诊断与预测→看板和报告→改进跟踪","dataScope":"采集监控、业务、ITSM和客服数据，计算评价指标并跟踪改进任务。","outputs":"周期性运行评价、触发任务、提醒责任人并组织复评。","collaboration":"DORA主承接：报告、解释和改进Agent。监控/BI平台：指标与异常。ITSM：任务闭环。人工：归因与责任分派。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"定义评价指标，确认问题归因，分派改进责任并组织复评。","before":"系统上线后的稳定性、使用、运维和客户反馈分散在多平台，评价偏重单项指标。","after":"监控、业务、ITSM和客服数据按统一口径形成全链路评价，问题自动分派并组织复评。","feedback":"“我能用一套口径看清系统上线后的真实表现，也能追踪每个改进项有没有解决。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"系统后评价报告准备时间减少60%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"评价数据采集覆盖率达到99%以上，核心指标一致率达到100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"改进任务按期闭环率达到90%以上，复评覆盖率达到95%以上。"}],"quantBasis":"Excel“独立场景库”TD-02。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"统一指标口径和数据责任；区分系统问题与业务流程问题；改进措施需明确责任人和复评。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA12-P01-S02","title":"科技需求全生命周期效能分析与资源调度","definition":"科技管理人员在需求全生命周期中统一查看价值、进度与资源负荷，识别堵点并形成经审批的优先级和调度建议。","decision":"AI-L3","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"partial","D04":"planned"},"role":"科技管理人员、项目经理、研发与测试负责人、需求提出部门","trigger":"需求受理、评审、排期、开发、测试、上线及周期复盘","task":"汇聚需求台账→统一价值与状态→识别超时和资源冲突→形成优先级建议→人工审批→跟踪交付","dataScope":"需求来源、类型、价值、成本、人日、状态、节点时长、变更、缺陷和资源排期。","outputs":"需求全景、超时清单、价值—成本矩阵、资源负荷预警、排期与催办建议。","collaboration":"Dora解释堵点并生成排期建议；需求系统维护正式状态；立项、预算、优先级和资源审批由人工完成。","manualCheck":"确认需求价值评分、优先级、预算、排期、资源调配和正式催办。","before":"各阶段状态、投入和业务价值分散记录，管理者难回答需求卡在哪里、团队是否过载以及哪些需求应优先。","after":"系统贯通需求六阶段并呈现价值—成本、进度和资源热力图，提示堵点并生成经审批的调度建议。","feedback":"“我能在一个视图里看清需求价值、卡点和未来资源缺口，排期讨论终于有统一依据。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"覆盖接收至上线6个阶段，汇总工时和交付周期下降目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"以5类25项指标监测变更、缺陷和文档完备性，超时率目标待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"形成需求价值—资源统一排序，高价值需求按期交付率目标待确认。"}],"scope":"已形成需求全景、生命周期、价值分级和资源负荷BI方案；自动归因和任务闭环仍需验证。","boundary":"价值评分不替代正式立项、预算、架构和合规审批；人员数据不得直接用于奖惩。","assets":{"方案 PPT":"已有","看板 Demo":"材料含原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]}]},{"id":"BA12-P02","name":"数据与模型治理","desc":"管理数据资产、质量问题和模型运营信息。","scenes":[{"id":"BA12-P02-S01","title":"元数据血缘驱动的数据变更影响分析","definition":"数据开发、治理与变更审批人员在数据变更评估环节，系统沿字段和表级血缘自动传播影响、解析SQL与ETL并输出证据链，高风险变更由人工审批。","decision":"AI-L3","maturity":"M2 方案验证 · 范围待核实","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"数据开发、治理与变更审批人员","trigger":"数据变更评估；业务对象或触发范围：字段删除、重命名、类型调整等单项或批量变更","task":"提交变更→沿表级和字段级血缘传播→解析SQL/ETL和风险规则→识别影响、吸收点和外部供数→输出证据链与人工复核项","dataScope":"检索元数据，解析SQL/ETL，沿血缘传播影响，生成清单和证据链。","outputs":"调用元数据、解析、图谱和报告工具，跟踪人工复核项。","collaboration":"DORA主承接：变更意图、解释和工具编排。元数据/血缘平台：事实与影响计算。变更系统：审批与实施。人工：确认和审批。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认候选血缘，审批高风险变更并制定实施与回退方案。","before":"数据变更影响依靠人员跨元数据、脚本和调度系统逐层追查，下游遗漏风险高。","after":"系统沿字段和表级血缘自动传播影响、解析SQL与ETL并输出证据链，高风险变更由人工审批。","feedback":"“我提交一个字段变更后很快就能看到受影响对象和证据，不再靠人肉逐层追查。”","metrics":[{"dimension":"效率","nature":"V03 实测参考","text":"一次端到端影响分析运行约18秒，排查由小时或天级缩短至分钟级。"},{"dimension":"质量/风险","nature":"V03 实测参考","text":"影响清单核对一致率达到100%，关键表字段级血缘覆盖率达到80%以上。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"高风险变更人工确认率保持100%，因漏评引发的下游故障下降30%以上。"}],"quantBasis":"Excel“独立场景库”TD-01。V03 仅代表材料中的局部测试参考；V01/V02 均不是已验证成效，正式立项需补充样本、周期、范围和统计口径。","scope":"材料包含局部测试或演示参考，可支持方案验证；真实客户、机构、用户、数据范围和生产化状态均待项目台账核实。","boundary":"AI只解释和编排，不创造血缘事实；候选血缘标注置信度；高风险结果人工确认。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA12-P02-S02","title":"敏感数据申请与授权审计","definition":"数据管理和审批人员审核敏感数据使用目的及范围，按最小授权配置访问权限并追踪查询记录。","decision":"AI-L1","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"done","D02":"na","D03":"partial","D04":"done"},"role":"数据管理人员、敏感数据审批部门、申请人","trigger":"敏感报表/指标申请、权限调整和使用检查","task":"按用途和最小范围审批数据访问并留下责任记录","dataScope":"申请用途、来源、计算逻辑、申请主体、审批权限和访问日志","outputs":"申请审批结果、授权记录、查询留痕与审计依据","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：数据权属与审批人员决定是否授权及可用范围，复核用途变更和异常；资料不全退回，不由AI放行。 程序/规则：承接申请、按批准范围配置权限并记录查询；有效期和自动回收是建议控制，案例材料未证实。 分析模型：可选异常访问检测需另验，不能用评分替代批准。 大模型：建议检查申请信息完整性、总结风险提示，不接触无权数据。 Agent：可建议汇总审批材料和提醒，不签批、不提权。","manualCheck":"数据权属与审批人员决定是否授权及可用范围，复核用途变更和异常；资料不全退回，不由AI放行。","before":"数据权限配置复杂，查看与导出边界及使用责任需要控制，敏感查询缺少明确申请和审批链会增加风险。","after":"新版案例材料描述一事一授权、谁用谁负责谁批谁负责，在线提交指标用途与逻辑后审核并配置权限，敏感查询留下记录；2021只证实分层权限控制。","feedback":"“我希望每次敏感数据开放都能说清谁申请、为何使用、谁批准，检查时能直接找到相应记录。”","metrics":[{"dimension":"效率","nature":"V00","text":"在线申请审核可减少线下往返，需补单笔授权办理时长、退回次数及申请范围。"},{"dimension":"质量/风险","nature":"V00","text":"案例材料称每笔敏感查询有记录，尚需用日志验证留痕完整率、越权阻断率和查看导出边界，不能直接记100%。"},{"dimension":"经营/管理","nature":"V00","text":"明确申请、审批与使用责任，需补到期回收率和审计定位时间，案例材料没有量化运营成效。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"申请—审批—权限配置及查询记录的案例陈述；不等于权限全生命周期验证；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"不为提高取数效率取消敏感审批；不凭平台publicRelease字段判定公开许可","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]},{"id":"BA12-P02-S03","title":"数据字段与码值目录维护","definition":"数据维护人员按主题登记和更新表字段及码值信息，供业务人员理解数据含义并复用授权数据资源。","decision":"AI-L1","maturity":"待核实 · AI增强建议未验证","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":false,"gateway":false,"values":["运营提效","风险合规"],"abilities":{"D01":"done","D02":"na","D03":"partial","D04":"partial"},"role":"科技/数据管理维护人员、业务数据责任人","trigger":"数据上架、字段码值变化、主题更新与周期维护","task":"提供统一、可理解且可维护的数据定义供业务复用","dataScope":"数仓表、字段含义、业务主题、码值及数据责任信息（责任字段是否已有待核）","outputs":"字段目录、码值说明、可复用数据主题与更新记录","collaboration":"当前为BI/程序案例基础，AI均为建议、非已实施能力。人工：数据责任人确认定义与码值、批准变更；存在歧义先标待核，不让大模型自行填补口径。 程序/规则：登记、分类、检索和展示字段码值；变更日志与一致性校验为建议控制，需补当前实现证据。 分析模型：核心维护不需要概率模型。 大模型：建议起草字段解释和发现疑似歧义，由数据责任人审核。 Agent：可建议组织待维护清单，不直接修改权威元数据或批准数据定义。","manualCheck":"数据责任人确认定义与码值、批准变更；存在歧义先标待核，不让大模型自行填补口径。","before":"业务人员不易知道平台有哪些数据及字段含义，主题和码值解释分散，容易产生重复沟通和误用。","after":"按业务主题登记字段与码值并提供查询，由维护人员定期更新；自动血缘、变更日志及全量治理范围需另行核实。","feedback":"“我希望业务问到一个字段时能找到一致的定义和码值说明，修改后也知道该由谁确认。”","metrics":[{"dimension":"效率","nature":"V00","text":"集中查找字段与码值含义，需补查询解释和维护单项定义的耗时，不据目录规模推算节省人天。"},{"dimension":"质量/风险","nature":"V00","text":"维护字段与码值2类说明，需补定义完整率、歧义率和更新及时率。"},{"dimension":"经营/管理","nature":"V00","text":"支持业务复用统一定义，需补复用率、重复需求变化及责任覆盖率，当前没有已验证成效数字。"}],"quantBasis":"可靠量化收益尚未取得；按效率、质量/风险、经营/管理补充基线、目标、周期和范围。","scope":"字段及码值目录维护与查询；字段级血缘和影响传播不在本证据范围；当前AI与Dora部署未验证，AI等级仅描述建议设计。","boundary":"权威定义由责任人维护，不能与现有变更影响分析卡混同","assets":{"方案 PPT":"待补独立文件","看板 Demo":"待核实","Dora 体验":"未验证","短视频":"暂无"},"sourceBatches":["B05"]}]}]},{"id":"BA13","mark":"风","name":"全面风险管理","desc":"面向客户、组合和资产质量开展持续监测、预警、处置与复盘，支持全行风险管理闭环。","sections":[{"id":"BA13-P01","name":"风险监测与预警","desc":"监测客户、组合和资产质量风险信号，识别异常、集中度与迁徙变化。","scenes":[{"id":"BA13-P01-S01","title":"绿色贷款资金用途一致性监测与漂绿预警","definition":"贷后管理人员、风险人员在放款核验、贷后监测环节，系统持续比对约定用途与真实流向，识别回流和用途偏离，自动形成证据链、核查清单与待办。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"贷后管理人员、风险人员","trigger":"放款核验、贷后监测；业务对象或触发范围：已获批或已投放的绿色贷款及其交易流水","task":"核验合同、发票、提款与收款对象→持续监测资金流向→识别异常回流和用途偏离→生成核查清单与贷后报告→人工处置","dataScope":"核对合同、发票、提款、收款对象和允许用途；执行金额与时效规则。","outputs":"持续调用交易监测、规则和报告服务，派发核查任务并跟踪结果。","collaboration":"DORA主承接：异常解释、核查清单和任务编排。交易监测/图谱服务：异常识别。核心与信贷系统：交易和贷后流程。人工：处置。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"复核异常交易，发起补充核查并决定风险处置。","before":"贷后人员依靠抽样检查合同、发票和交易流水，异常资金流向发现晚、准备核查材料慢。","after":"系统持续比对约定用途与真实流向，识别回流和用途偏离，自动形成证据链、核查清单与待办。","feedback":"“我能先看到异常资金去了哪里以及为什么可疑，再把时间放在核实和处置上。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"材料初审时间减少60%以上，异常调查准备时间减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"重点交易链路证据覆盖率达到95%以上，高风险异常人工复核率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"异常核查任务按期闭环率达到90%以上，重复补取材料次数下降30%以上。"}],"quantBasis":"Excel“独立场景库”CP-06。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"建立项目允许用途清单和交易证据链；异常只作为核查线索；处置由有权人员决定。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA13-P01-S02","title":"资产质量全景监测、推演与管控建议","definition":"全面风险与资产质量管理人员在风险监测、分析与管理决策环节，统一看板持续计算结构、迁徙与集中度，结合宏观信息完成趋势推演和管理分析初稿。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["管理决策","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"planned"},"role":"全面风险与资产质量管理人员","trigger":"风险监测、分析与管理决策；业务对象或触发范围：全行贷款与非正常贷款组合","task":"汇集资产质量与外部宏观信息→统一看板→识别结构与趋势问题→情景推演和原因分析→形成管控建议","dataScope":"汇总贷款与不良资产明细，计算结构、迁徙和集中度指标并展示看板。","outputs":"定时调用数据、推演和报告服务，形成管理分析包。","collaboration":"本轮案例的人工与程序基础、AI增强建议分别为：人工：核实贷款分类、口径及重点风险，决定核查与管控；异常数据退回核对，不自动调分类或处置。 程序/规则：计算质量指标、完成率与机构分布并提供明细比较，正式分类规则需银行确认。 分析模型：可选趋势推演另行验证，本批不声称部署。 大模型：建议生成变化摘要和核查提纲，不能定性风险成因。 Agent：可建议汇集风险材料；正式处置转交授权风控流程。 本轮不构成Dora或联合Agent已部署证明。","manualCheck":"确认分析假设和重点风险，审定资产质量管控措施。","before":"资产质量分析依赖人工汇总多套明细和外部信息，形成管理报告慢且难做情景推演。","after":"统一看板持续计算结构、迁徙与集中度，结合宏观信息完成趋势推演和管理分析初稿。","feedback":"“我可以直接查看统一口径的资产质量变化，并把时间用于验证假设和制定管控措施。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"每月节省约10人天的汇总与报告准备工作。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"核心资产质量指标一致率达到100%，重点风险证据覆盖率达到95%以上。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"月度管理分析准备周期缩短50%以上，重点管控事项按期闭环率达到90%以上。"}],"quantBasis":"Excel“独立场景库”CR-07。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。 本轮案例补充范围：质量现状、变化和机构对比；预测/情景推演及处置流转未证实；不据此升级整卡成熟度或AI实施状态。","boundary":"原课题使用虚拟数据，必须先以真实生产数据验证口径、推演假设和建议有效性。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B04","B05"]},{"id":"BA13-P01-S03","title":"个人贷款组合全景监测与集中度预警","definition":"零售信贷风险管理人员在贷后与组合监测环节，组合明细自动汇总并按多维阈值持续监测，异常趋势触发解释、预警和处置任务。","decision":"AI-L2","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["管理决策","运营提效","风险合规"],"abilities":{"D01":"partial","D02":"partial","D03":"planned","D04":"planned"},"role":"零售信贷风险管理人员","trigger":"贷后与组合监测；业务对象或触发范围：个人贷款组合及机构、产品、区域等集中度维度","task":"汇总个贷明细→按机构、产品、客群和区域监测→识别集中度及异常趋势→生成预警与分析报告→跟踪处置","dataScope":"汇总个贷明细，按机构、产品、区域和客群计算组合指标并预警。","outputs":"定时刷新指标、调用异常检测并派发预警任务。","collaboration":"DORA辅助承接：自然语言问数、报告和预警编排。BI/风险平台：组合计算。信贷系统：明细。人工：阈值和处置。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"设定集中度阈值，确认预警原因并决定组合调整。","before":"个贷组合数据分散，机构、产品和区域集中度主要靠临时取数和事后分析。","after":"组合明细自动汇总并按多维阈值持续监测，异常趋势触发解释、预警和处置任务。","feedback":"“我能随时看到个贷组合哪里在集中、变化有多快，不用临时找人取数。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"组合监测报表准备时间减少70%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"重点集中度指标覆盖率达到95%以上，阈值命中事项人工确认率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"高风险组合预警24小时内分派率达到90%以上，月度分析周期缩短50%以上。"}],"quantBasis":"Excel“独立场景库”CR-10。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"先定义集中度阈值和处置责任；避免把相关性直接解释为风险成因。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]},{"id":"BA13-P01-S04","title":"重点信贷产品全流程风险监测与策略复盘","definition":"风险与产品管理人员持续监测重点信贷产品的贷前、贷中、贷后和规则表现，识别风险点并形成策略复盘建议。","decision":"AI-L2","maturity":"M2 方案验证","version":"v1.0","flagship":false,"gateway":false,"values":["风险合规","管理决策","运营提效"],"abilities":{"D01":"done","D02":"partial","D03":"planned","D04":"planned"},"role":"风险管理人员、信贷产品经理、授信审查人员和部门负责人","trigger":"日常产品风险监测、预警指标触发、规则复盘和产品策略调整前","task":"监测产品规模与风险→分析贷前准入和定价→分析贷中用信→跟踪逾期与不良→复盘规则触发→形成策略优化建议","dataScope":"产品规模与收益、进件和拒绝、准入特征、利率定价、用信率、逾期与不良、规则触发、机构与客户经理。","outputs":"产品风险总览、贷前贷中贷后分析、规则触发分析、预警信息和策略复盘建议。","collaboration":"当前以BI指标、预警阈值和看板为主；后续可由Dora或联合Agent生成异动归因、规则复盘和报告。","manualCheck":"确认风险口径、产品预警、规则调整、定价建议和授信政策变化。","before":"产品规模、收益、准入、用信、逾期、不良和规则数据分散在不同环节，跨阶段复盘依赖人工汇总，问题发现较慢。","after":"BI看板将产品关键指标按贷前、贷中、贷后和规则统一呈现，并支持机构、客户经理和客群下钻，由相关人员共同确认优化建议。","feedback":"“我能沿着一个产品的全流程看到风险在哪里形成、哪些规则需要复盘，不再只看最终不良结果。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"需补充跨环节数据汇总与产品复盘人时的基线和目标。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"需补充预警命中率、规则复盘覆盖率和数据一致性目标。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"需补充高风险产品识别、规则优化周期和风险收益改善指标。"}],"quantBasis":"昆山BI大赛重点产品全流程风控作品未提供正式试点成效。","scope":"已覆盖全行信贷产品总览及线上经营备用金的贷前、贷中、贷后和规则分析；其他产品和策略闭环尚待扩展。","boundary":"不替代单笔授信审批、客户风险定性和正式规则发布；相关变化必须经有权人员审批。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"暂无","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B03","B04"]},{"id":"BA13-P01-S05","title":"收单商户交易风险监测与核查督办","definition":"风控人员对收单商户五维风险信号进行分级、穿透和督办，把异常提示转成经人工核查的处置闭环。","decision":"AI-L3","maturity":"M2 方案验证 · 生产范围待核实","version":"v0.1","flagship":false,"benchmark":false,"digitalTalent":true,"gateway":false,"values":["风险合规","运营提效","管理决策"],"abilities":{"D01":"done","D02":"done","D03":"partial","D04":"partial"},"role":"总行风控负责人、区域风控经理、支行风控执行岗","trigger":"每日批量监测、风险阈值命中、区域风险上升或核查任务超期时","task":"汇聚商户交易→执行五维规则→分级排序→生成佐证与清单→人工核查→督办→优化规则","dataScope":"商户资质、交易时段与金额、支付ID和卡号关联、行业区域、结算周期和退款。","outputs":"风险商户分级、触发指标、交易佐证、区域热力图、核查任务和处置反馈。","collaboration":"规则平台执行监测，Dora解释信号并生成核查指引；工单系统记录处置，停用或限额由授权人员决定。","manualCheck":"确认风险等级、核查真实性、现场结论、处置措施、规则阈值和结案。","before":"风险名单依赖邮件和Excel流转，通常只有模糊对象，没有原因、交易证据和标准核查步骤。","after":"系统每日运行五维规则，呈现触发原因和佐证，按风险等级派发核查清单并提醒超期任务。","feedback":"“我收到的不再是一张模糊名单，而是带触发原因、交易佐证和核查步骤的任务。”","metrics":[{"dimension":"效率","nature":"V00 待确认","text":"每日自动批处理覆盖5类风险维度，汇总周期和单户核查时长目标待确认。"},{"dimension":"质量/风险","nature":"V00 待确认","text":"规则含深夜交易占比≥30%等阈值，命中准确率、误报率和闭环率待确认。"},{"dimension":"经营/管理","nature":"V00 待确认","text":"同时服务总行、区域和支行3层，超期任务下降和策略迭代周期目标待确认。"}],"scope":"已有五维规则、三层级看板和每日批处理方案；工单集成与模型效果待核实。","boundary":"风险信号只是核查线索，不自动认定违规、欺诈或停用商户。","assets":{"方案 PPT":"已有","看板 Demo":"材料含原型","Dora 体验":"待建设","短视频":"暂无"},"sourceBatches":["B04"]}]},{"id":"BA13-P02","name":"风险处置与资产质量","desc":"对重点风险实施核查、处置、清收和复盘，推动风险管理闭环。","scenes":[{"id":"BA13-P02-S01","title":"贷后风险信号降噪、联动传播与处置闭环","definition":"贷后管理与风险处置人员在监测、核查、处置、复盘环节，信号自动去重、关联传播和分级，生成差异化核查与处置建议，并以结果回流优化规则。","decision":"AI-L3","maturity":"M2 方案验证","version":"v0.2","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"贷后管理与风险处置人员","trigger":"监测、核查、处置、复盘；业务对象或触发范围：授信客户、关联企业、担保圈和产业链","task":"风险信号标准化去重→关联图谱传播→风险分级→生成差异化检查和处置方案→督办跟踪→以结果反哺规则","dataScope":"统一、去重预警信号，执行阈值规则、任务流转、督办和留痕。","outputs":"编排信号感知、关联传播、分级处置与规则迭代。","collaboration":"DORA主承接：多Agent编排、解释和材料生成。图谱/模型服务：风险计算。贷后系统：任务闭环。人工：风险定性与处置。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认风险性质，选择检查方案和处置措施，复盘规则有效性。","before":"预警信号重复且虚警较多，关联客户风险靠人工串联，处置经验难以反哺规则。","after":"信号自动去重、关联传播和分级，生成差异化核查与处置建议，并以结果回流优化规则。","feedback":"“我先处理最值得核查的风险，也能看到关联传播路径，排查不再被重复预警淹没。”","metrics":[{"dimension":"效率","nature":"V01 申报目标","text":"预警调查时间减少40%以上，风险处置效率提升50%以上。"},{"dimension":"质量/风险","nature":"V01 申报目标","text":"优化约30%的低效预警规则，风险识别准确性提升50%以上。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"重点预警7日内闭环率达到90%以上，处置结果有效回流率达到95%以上。"}],"quantBasis":"Excel“独立场景库”CR-06。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"已有昆山 BI 大赛作品提供可追溯的 BI 实现路径；AI、联合 Agent 和业务闭环范围仍按场景边界继续验证。","boundary":"分开管理事实、模型推断和处置建议；风险传播需要阈值与证据链；高风险处置人工审批。","assets":{"方案 PPT":"作品介绍已有","看板 Demo":"已有材料截图","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":true,"sourceBatches":["B02","B03","B04"]},{"id":"BA13-P02-S02","title":"已核销资产回款概率评分与清收策略","definition":"资产保全与清收人员在核销后清收环节，案件按回款概率和关键因子排序，匹配差异化清收策略并以结果回录持续复评。","decision":"AI-L3","maturity":"M1 需求确认","version":"v0.1","flagship":false,"gateway":false,"values":["风险合规","运营提效"],"abilities":{"D01":"partial","D02":"partial","D03":"partial","D04":"partial"},"role":"资产保全与清收人员","trigger":"核销后清收；业务对象或触发范围：已核销贷款客户及清收任务","task":"整合多系统清收数据→回款归因→回款概率评分→客群排序与差异化策略→回录清收结果→迭代模型","dataScope":"整合清收台账、分配任务、执行策略规则并记录结果。","outputs":"编排评分、任务分配、提醒、结果回流和模型复评。","collaboration":"DORA主承接：策略解释、任务编排和结果复盘。模型服务：回款预测。清收系统：作业与留痕。人工：催收和策略确认。 协作形态为 C02 业务系统嵌入调用与 C04 Dora 外接能力；来源材料未明确联合 Agent。","manualCheck":"确认清收优先级与策略，执行合规催收并回录结果。","before":"核销案件按经验分配清收资源，历史回款特征和策略效果难以形成可复用依据。","after":"案件按回款概率和关键因子排序，匹配差异化清收策略并以结果回录持续复评。","feedback":"“我能先跟进更可能回款的案件，并清楚知道推荐顺序背后的关键因素。”","metrics":[{"dimension":"效率","nature":"V02 建议试点目标","text":"案件筛选与任务分配时间减少50%以上。"},{"dimension":"质量/风险","nature":"V02 建议试点目标","text":"高优先级案件解释覆盖率达到95%以上，催收合规检查覆盖率保持100%。"},{"dimension":"经营/管理","nature":"V02 建议试点目标","text":"单位人力回款金额提升10%以上，清收结果有效回录率达到90%以上。"}],"quantBasis":"Excel“独立场景库”CR-08。所列数字为申报或建议目标，不是已验证成效；正式立项需确认基线、样本、周期、范围和统计口径。","scope":"来源材料已明确业务对象、主要动作和预期价值；原型、试点或生产状态及覆盖范围均待项目台账核实。","boundary":"处理好个人信息和催收合规；模型不得触发不当差别化催收；定期监控偏差。","assets":{"方案 PPT":"待提炼","看板 Demo":"待核实","Dora 体验":"待核实","短视频":"暂无"},"benchmark":false,"digitalTalent":false,"sourceBatches":["B02"]}]}]}],"departments":[{"id":"DP01","name":"零售金融部","aliases":["个人金融部","零售业务部"],"scope":"个人客群、营销、存量维护和零售经营；财富投资适当性由财富职责承担。"},{"id":"DP02","name":"财富管理部","aliases":["私人银行部","财富中心"],"scope":"财富客户、理财产品经营及配置建议；不代表金融市场自营投资。"},{"id":"DP03","name":"公司金融部","aliases":["公司业务部","企业金融部"],"scope":"对公客户拓展、综合经营、票据服务与授信协同。"},{"id":"DP04","name":"交易银行部","aliases":["现金管理部","结算与现金管理部"],"scope":"为企业客户提供CBS、账户与资金服务；企业使用者不作为银行部门。"},{"id":"DP05","name":"普惠金融部","aliases":["小微金融部"],"scope":"小微客户获客、网格走访、续贷和综合服务；三农职责需按客户机构适配。"},{"id":"DP06","name":"金融市场部","aliases":["资金业务部","同业业务部"],"scope":"自营投研、组合管理与同业业务；不默认承担资管或托管运营。"},{"id":"DP07","name":"渠道管理部","aliases":["渠道与网点管理部"],"scope":"网点布局、渠道资源及线上线下转介；厅堂作业与排班由运营职责核对。"},{"id":"DP08","name":"网络金融部","aliases":["电子银行部","数字银行部"],"scope":"收单商户、数字渠道产品及场景金融运营。"},{"id":"DP09","name":"客户服务中心","aliases":["远程银行部","电话银行中心"],"scope":"视频银行、客户导航、投诉处理；消保监督责任与受理作业分开。"},{"id":"DP10","name":"消费者权益保护部","aliases":["消保部"],"scope":"投诉归因与消保整改治理，不将所有营销服务都自动映射至消保。"},{"id":"DP11","name":"运营管理部","aliases":["运营部","集中作业中心"],"scope":"柜面与集中作业、厅堂排班、现金作业及业务模板处理。"},{"id":"DP12","name":"授信审批部","aliases":["授信审查部","信贷审批部"],"scope":"准入审查、审批效能、财务初筛和放款条件核验；按授权核定具体职责。"},{"id":"DP13","name":"信贷管理部","aliases":["授信管理部"],"scope":"授信政策、投放结构、贷后核查和产品信贷管理；不与独立审批混同。